const a={id:"hsk5",category:"written",badgeJa:"HSK 5級",titleJa:"HSK 3.0（5級）公式様巻演習",officialTitle:"中文水平考试 HSK（五级）样卷",cefrTag:"CEFR C1 · 中上級",levelGroup:"advanced",totalQuestions:72,examMinutes:105,totalScore:300,passScore:180,defaultShowPinyin:!1,sectionsSummaryJa:[{section:"listening",labelJa:"聴力（リスニング）",count:35,minutesJa:"約25分"},{section:"reading",labelJa:"読解（リーディング）",count:35,minutesJa:"35分"},{section:"writing",labelJa:"書写（ライティング）",count:2,minutesJa:"40分"}],audioUrl:"../HSK3.0_新版样卷/五级/样卷_录音.mp3",audioDurationSeconds:1591.9,pdfQuestionUrl:"../HSK3.0_新版样卷/五级/样卷_题目.pdf",pdfAnswerUrl:"../HSK3.0_新版样卷/五级/样卷_答案.pdf",officialNoteJa:"リスニング終了後に5分間の解答用紙記入時間があります（全試験時間105分、個人情報記入を含め約110分）。"},t=[{id:"L1",section:"listening",sectionTitleJa:"一、聴力",titleJa:"第1部",shortLabelJa:"聴力1",subtitleJa:"対話聴解（4択）",questionRange:[1,19],instructionJa:"第1〜19問：対話を1回だけ聞き、質問に対する正しい答えをA〜Dから選んでください（第1〜10問は1対話1問、第11〜19問は長めの対話から2〜3問出題）。",audioIntro:{start:0,end:68.55}},{id:"L2",section:"listening",sectionTitleJa:"一、聴力",titleJa:"第2部",shortLabelJa:"聴力2",subtitleJa:"短文聴解（4択）",questionRange:[20,35],instructionJa:"第20〜35問：短文（アナウンス・文化解説・故事・ニュース・心理解説など）を1回だけ聞き、各質問に対する正しい答えをA〜Dから選んでください。",audioIntro:{start:840.4,end:853.45}},{id:"R1",section:"reading",sectionTitleJa:"二、読解",titleJa:"第1部",shortLabelJa:"読解1",subtitleJa:"総合空欄補充（クローズテスト）",questionRange:[36,45],instructionJa:"第36〜45問：3つの短文を読み、空欄に入る最も適切な語句・フレーズをA〜Dから選んでください。"},{id:"R2",section:"reading",sectionTitleJa:"二、読解",titleJa:"第2部",shortLabelJa:"読解2",subtitleJa:"段落並べ替え",questionRange:[46,55],instructionJa:"第46〜55問：5つの段落（A〜E）を論理・時間の流れに沿って正しく並べ替え、1番目〜5番目に入る段落を選んでください。"},{id:"R3",section:"reading",sectionTitleJa:"二、読解",titleJa:"第3部",shortLabelJa:"読解3",subtitleJa:"長文読解（4択）",questionRange:[56,70],instructionJa:"第56〜70問：4つの長文を読み、各設問に対する最も適切な答えをA〜Dから選んでください。"},{id:"W1",section:"writing",sectionTitleJa:"三、書写",titleJa:"第1部",shortLabelJa:"書写1",subtitleJa:"4コマ漫画作文（100字以上）",questionRange:[71,71],instructionJa:"第71問：4枚のイラストを見て、李明と仲間たちに起きた出来事を100字以上の中国語で書いてください。"},{id:"W2",section:"writing",sectionTitleJa:"三、書写",titleJa:"第2部",shortLabelJa:"書写2",subtitleJa:"テーマ作文（200字以上）",questionRange:[72,72],instructionJa:"第72問：「尝试（試み・挑戦）」というテーマについて、自分自身の経験とその感想を200字以上の中国語で書いてください。"}],e=JSON.parse('{"hsk5-l1-11-12":{"id":"hsk5-l1-11-12","titleJa":"第11〜12問 共通対話（写真の構図と「留白」）","instructionJa":"次の対話を聞いて、第11〜12問に答えてください。","audio":{"start":460.15,"end":529.35},"transcript":[{"speaker":"女","text":"你照片里的内容太杂了，摄影也要讲究留白。","ja":"あなたの写真は要素がごちゃごちゃしすぎているわ。写真撮影でも「余白（留白）」を重視しないと。"},{"speaker":"男","text":"什么是留白？","ja":"「留白」って何ですか？"},{"speaker":"女","text":"留白源于国画创作，是指为了使画面更有诗意，故意留下空白。","ja":"留白は中国画の創作に由来していて、画面により詩情を持たせるためにあえて空白を残すことを指すの。"},{"speaker":"男","text":"你的意思是要留下更多想象的空间？","ja":"つまり、想像の余地をもっと残すということですか？"},{"speaker":"女","text":"没错，带给人想象的同时，还要让人关注到照片的主题。比如这张落日的照片，要是你能把更多的画面留给天空和大海，那么照片会更有意境，主题也更突出。","ja":"その通り。見る人に想像させるのと同時に、写真のテーマに目を向けさせるのよ。例えばこの夕日の写真なら、画面のより多くの部分を空と海に割けば、もっと趣が出てテーマも際立つわ。"},{"speaker":"男","text":"明白了，我还要再练练构图技巧。","ja":"わかりました。構図のテクニックをもっと練習しないとですね。"}],"passageJa":"女：あなたの写真は要素が雑多すぎますね。写真でも余白（留白）を大切にしないと。\\n男：留白とは何ですか？\\n女：留白は中国画に由来し、画面に詩情を出すためにわざと空白を残すことです。\\n男：想像の余地をもっと残すという意味ですね？\\n女：ええ。想像を広げつつ写真の主題に注目させるのです。例えばこの夕日の写真も、空と海にもっと画面を割けば趣が増し、主題もより際立ちます。\\n男：わかりました。構図のコツをもっと練習します。"},"hsk5-l1-13-14":{"id":"hsk5-l1-13-14","titleJa":"第13〜14問 共通対話（テニス選手とコーチの対談）","instructionJa":"次の対話を聞いて、第13〜14問に答えてください。","audio":{"start":544.4,"end":615.15},"transcript":[{"speaker":"男","text":"这次网球公开赛打得不错，你有什么感想？","ja":"今回のテニスオープン大会はよく戦えたね。どんな感想を持っている？"},{"speaker":"女","text":"教练，这次比赛让我深刻体会到，即使这一球失误了，也不要轻易放弃，要立刻调整好心态，尽力把下一球赢下来。","ja":"コーチ、今回の試合で痛感したのは、たとえこの1球でミスをしても簡単に諦めず、すぐ気持ちを切り替えて次の1球を全力で取りにいくべきだということです。"},{"speaker":"男","text":"没错，你现在排名上升了，但也不要有太大压力。","ja":"その通りだ。今はランキングも上がったが、あまり大きなプレッシャーを感じなくていいよ。"},{"speaker":"女","text":"明白，我现在也反复提醒自己，不要过多考虑结果，专注于比赛的每一刻才是最重要的。","ja":"わかりました。今は自分にも何度も言い聞かせているんです。結果を考えすぎず、試合の一瞬一瞬に集中することが一番大切だと。"},{"speaker":"男","text":"嗯，你现在还希望成为下一个李娜吗？","ja":"うん。今でも「次の李娜（リー・ナ）」になりたいと思っているかい？"},{"speaker":"女","text":"曾经她是我努力的目标，但现在我想做的就是挑战自我，能不断进步就好。","ja":"かつては彼女が努力の目標でしたが、今やりたいのは自分自身への挑戦で、絶えず進歩し続けられればそれでいいんです。"}],"passageJa":"男（コーチ）：今回のテニスオープンは良い出来だったね。感想は？\\n女（選手）：今回の試合で、たとえ1球ミスしてもすぐ諦めず、即座にメンタルを立て直して次の1球を全力で取る大切さを痛感しました。\\n男：その通り。ランキングは上がったがプレッシャーを抱えすぎないように。\\n女：はい。結果を気にしすぎず試合の毎瞬間に集中しようと自分に言い聞かせています。\\n男：今でも次の李娜を目指している？\\n女：かつては彼女が目標でしたが、今は自分への挑戦、つまり進歩し続けることが目標です。"},"hsk5-l1-15-16":{"id":"hsk5-l1-15-16","titleJa":"第15〜16問 共通対話（お掃除ロボットのプレゼント）","instructionJa":"次の対話を聞いて、第15〜16問に答えてください。","audio":{"start":629.9,"end":695.05},"transcript":[{"speaker":"女","text":"你送的这个扫地机器人我不太会用。","ja":"あなたがくれたこのお掃除ロボット、使い方がよくわからないの。"},{"speaker":"男","text":"我已经设置好了打扫路线，您用的时候直接开机就行。","ja":"掃除ルートはもう設定しておいたから、使うときはそのまま電源を入れるだけで大丈夫ですよ。"},{"speaker":"女","text":"那会不会碰坏家具？","ja":"家具にぶつかって壊したりしないかしら？"},{"speaker":"男","text":"放心，扫地机器人里安装了先进的传感器系统，就像它的眼睛，能灵活避开家具。","ja":"安心してください。お掃除ロボットの中には先進的なセンサーシステムが搭載されていて、まるで「目」のように柔軟に家具を避けられるんです。"},{"speaker":"女","text":"现在的机器真智能，是不是很贵呀？","ja":"最近の機械は本当に賢いのね。すごく高かったんじゃない？"},{"speaker":"男","text":"正好商场在做促销活动，我就买了，而且还提供两年售后保障服务，一年内免费更换新机，您就放心用吧。","ja":"ちょうどショッピングモールでセール中だったので買ったんです。それに2年間のアフター保証が付いていて、1年以内なら無料で新品と交換してもらえますから、安心して使ってください。"}],"passageJa":"女：もらったお掃除ロボットの使い方がよくわからないわ。\\n男：ルートは設定済みなので電源を入れるだけでOKです。\\n女：家具を傷つけないかしら？\\n男：大丈夫、先進的なセンサーシステムが目の役割を果たして家具を巧みに避けます。\\n女：賢いのね、高かったのでは？\\n男：ちょうど店舗でセール中だったんです。2年保証付きで1年以内なら無料新品交換なので安心して使ってください。"},"hsk5-l1-17-19":{"id":"hsk5-l1-17-19","titleJa":"第17〜19問 共通対話（青少年のメンタルヘルスと親の役割）","instructionJa":"次の対話を聞いて、第17〜19問に答えてください。","audio":{"start":709.95,"end":825.6},"transcript":[{"speaker":"女","text":"您觉得当前社会，家长对孩子心理疾病的了解程度怎么样？","ja":"現代社会において、保護者の子どもの心の病に対する理解度はどの程度だとお考えですか？"},{"speaker":"男","text":"虽然有不少宣传，但从整体上来说，了解得还是不够。有的家长不承认或不理解孩子的心理问题，还有的家长觉得有心理问题很丢脸，怕老师知道了影响孩子评优、升学。","ja":"啓発活動は少なくありませんが、全体としてはまだまだ理解が不十分です。子どもの心の問題を認めなかったり理解できなかったりする親もいますし、心の問題があることを恥ずかしいと感じ、先生に知られると優秀生徒の評価や進学に影響すると恐れる親もいます。"},{"speaker":"女","text":"那遇到需要帮助的青少年和家长时，您通常会怎么做？","ja":"では、支援を必要とする青少年や保護者に出会ったとき、普段どのように対応されますか？"},{"speaker":"男","text":"我更关注家长的作用，我会跟家长说，只有孩子去接受咨询是不够的，家长必须先参与进来。父母得先从自己做起，发自内心地去改变，孩子才能体会到这种变化，进而跟着改变。","ja":"私は親の役割をより重視しています。子どもだけがカウンセリングを受けても不十分で、まず親が参加しなければならないと伝えます。親がまず自分自身から心から変わってこそ、子どもはその変化を感じ取り、それに伴って変わっていけるのです。"},{"speaker":"女","text":"在家庭教育里，怎么才能和孩子建立良好的关系呢？","ja":"家庭教育の中で、どうすれば子どもと良好な関係を築けるのでしょうか？"},{"speaker":"男","text":"要尊重孩子，听他们说话时别急着下结论，要试着理解他们的感受，这样孩子才更愿意和家长交流，分享他们的内心世界。","ja":"子どもを尊重し、話を聞くときに急いで結論を出さず、彼らの気持ちを理解しようと努めることです。そうすれば子どもはもっと親と話し、心の内を打ち明けたくなるものです。"}],"passageJa":"女：現在、保護者の子どもの心の病への理解度はいかがですか？\\n男：啓発はあるものの全体的には理解不足です。問題を認めない親や、先生に知られて進学に響くのを恐れて恥ずかしがる親もいます。\\n女：支援が必要な青少年と保護者にはどう対応しますか？\\n男：親の役割を重視し、子どもだけでなくまず親自身が参加して変わることが必要だと伝えます。\\n女：家庭教育で良好な親子関係を築くには？\\n男：子どもを尊重し、話を聞くとき性急に結論づけず気持ちを理解しようと努めることが大切です。"},"hsk5-l2-20-21":{"id":"hsk5-l2-20-21","titleJa":"第20〜21問 共通短文（G53次高速鉄道の車内アナウンス）","instructionJa":"次の短文を聞いて、第20〜21問に答えてください。","audio":{"start":856.8,"end":924.4},"transcript":[{"speaker":"男","text":"旅客朋友们大家好，欢迎乘坐G53次列车，我是本次列车的列车长。本次列车由北京开往重庆，发车时间下午三点整。受暴雨天气影响，列车晚点半个小时，实际运行时间为七小时三十分钟。对此，我代表全体列车工作人员对给您带来的不便表示歉意。我们即将到达本次列车的终点站重庆北站，请旅客朋友们提前做好准备，带好行李，有序下车。","ja":"乗客の皆様こんにちは。G53次列車にご乗車いただきありがとうございます。私は本列車の車掌長です。本列車は北京発重慶行き、発車時刻は午後3時ちょうどでした。豪雨の影響により30分遅延し、実際の運行時間は7時間30分となりました。この件につきまして、乗務員一同を代表し、ご不便をおかけしたことを深くお詫び申し上げます。まもなく終点の重慶北駅に到着いたします。お早めに降車の準備を整え、お荷物をお忘れのないよう、順序よくお降りください。"}],"passageJa":"乗客の皆様こんにちは。G53次列車へようこそ。私は本列車の車掌長です。北京発重慶行きの本列車は午後3時発車でしたが、豪雨の影響で30分遅れ、実際の所要時間は7時間30分となりました。乗務員一同、ご不便をお詫びいたします。まもなく終点の重慶北駅に到着します。お荷物をまとめて順序よくお降りください。"},"hsk5-l2-22-23":{"id":"hsk5-l2-22-23","titleJa":"第22〜23問 共通短文（現代のアウトドア「捡秋（秋拾い）」）","instructionJa":"次の短文を聞いて、第22〜23問に答えてください。","audio":{"start":940.15,"end":1025.55},"transcript":[{"speaker":"男","text":"以前到了秋天，农民们收获完成熟的粮食等农作物后，地里往往还有遗落的部分。为了避免浪费，农民会再次回到地里捡，这就叫做“捡秋”。随着生活方式的转变，“捡秋”逐渐变成一种新的户外活动形式。现在的“捡秋”更多是指在秋天时，人们走到户外，捡落叶、果实等以感受大自然，享受秋天的美好。需要注意的是，参与“捡秋”活动时要保护环境，尽量减少对自然资源的破坏，尤其是在捡果实和落叶时不要过度采集，避免影响小动物们的生存。此外，户外活动时要注意安全，最好和伙伴一起行动，提前了解天气、活动地点等状况，确保活动安全顺利地开展。","ja":"昔、秋になると農民たちは熟した穀物などの農作物を収穫した後、畑に落ち残った分を無駄にしないよう再び拾いに行きました。これを「捡秋（秋拾い）」と呼びます。生活様式の変化に伴い、「捡秋」は次第に新しいアウトドア活動へと変わりました。現在の「捡秋」は主に秋に野外へ出て落ち葉や木の実などを拾い、大自然を感じて秋の美しさを楽しむことを指します。注意すべき点として、参加する際は環境を守り自然資源への破壊を極力減らすこと、特に木の実や落ち葉を過度に採取して小動物の生存に影響を与えないようにすることが挙げられます。また安全に留意し、なるべく仲間と一緒に行動し、天候や場所の状況を事前に確認して安全かつ円滑に行うことが大切です。"}],"passageJa":"昔、農民が収穫後に畑へ落ちた作物を拾うことを「捡秋」と呼んでいましたが、今では秋に野外へ出て落ち葉や木の実を拾い、自然を味わう新しいアウトドア活動になっています。参加時は環境保護に配慮して過度な採取を控え、小動物の生態に影響を与えないこと、また安全のため仲間と行動し事前に天候や場所を確認することが大切です。"},"hsk5-l2-24-26":{"id":"hsk5-l2-24-26","titleJa":"第24〜26問 共通短文（蘇洵のユニークな子育て法）","instructionJa":"次の短文を聞いて、第24〜26問に答えてください。","audio":{"start":1041.3,"end":1155.4},"transcript":[{"speaker":"女","text":"苏洵少时不爱读书，只喜欢游山玩水，直到27岁才开始努力学习。因为自己读书晚，他深知年少读书的重要性，便教导两个儿子苏轼、苏辙从小读书。但苏洵多次劝说也没有效果，他决定改变教育孩子的方法。后来，他想出了个好主意。苏洵每次看书时，都故意躲到角落里去，而且只要两个孩子一靠近，他便赶紧把书藏起来。这激发了兄弟俩的好奇心：父亲为什么要背着他们看书？书里面到底有什么好玩的？于是，他俩趁苏洵不在时，把他藏的书找出来，认真地读起来。慢慢地，两个孩子对书产生了浓厚的兴趣，开始广泛阅读，为日后成为著名文学家打下了基础。","ja":"蘇洵は若いころ勉強が嫌いで、山川を巡って遊ぶことばかりを好み、27歳になってようやく必死に学び始めました。自分が学問を始めたのが遅かったため、若いうちに学ぶ大切さを痛感し、蘇軾・蘇轍の二人の息子に幼いころから読書を教えようとしました。しかし何度も諭しても効果がなく、教育法を変えることにしたのです。やがて良いアイデアを思いつき、蘇洵は本を読むたびにわざと部屋の隅に隠れ、子どもたちが近づくと慌てて本を隠しました。これが兄弟の好奇心を刺激し、「父はどうして隠れて本を読むのか、中に面白いものでもあるのか」と気になり、蘇洵の留守中に隠された本を探し出して熱心に読むようになりました。次第に二人は読書に深い興味を持ち幅広く読むようになり、後に著名な文学者となる礎を築いたのです。"}],"passageJa":"蘇洵は若いころ遊山ばかりで27歳から学び始めたため、息子の蘇軾・蘇轍には幼少期から読書させようとしました。説得が効かないとわかると、あえて隅に隠れて本を読み、子どもが近づくと本を隠す作戦を実行。好奇心をくすぐられた兄弟は父の留守中に本を探して読むようになり、やがて広く読書して著名な文学者となる基盤を築きました。"},"hsk5-l2-27-29":{"id":"hsk5-l2-27-29","titleJa":"第27〜29問 共通短文（事故に遭った農家を助けた交通警察）","instructionJa":"次の短文を聞いて、第27〜29問に答えてください。","audio":{"start":1171.15,"end":1295.25},"transcript":[{"speaker":"女","text":"深夜，浙江宁波镇海交警大队接到一起交通事故报警。菜农曹先生在运送蔬菜途中，不幸遇到交通事故。幸运的是，曹先生受伤并不严重，随后120及时赶到，将他送往医院治疗。但事故现场，十筐蔬菜散落一地，成了急需解决的新难题。曹先生仍在医院，无法赶往现场，他表示，即使蔬菜没坏，第二天也很难再卖出去。事故组组长徐震在与同事们商量后，一致决定将蔬菜整理后运送到中队。随后，中队的民辅警们纷纷主动提供帮助，按照市场价格，一人一袋，将剩余蔬菜全部买走。第二天，曹先生的妻子特意赶到中队，向民辅警们表达感激之情：“真的太感谢你们了，帮我们减少了不少损失。”民辅警们则谦虚地表示，大家生活都不容易，希望能给大家送去些许温暖。","ja":"深夜、浙江省寧波市鎮海区の交通警察大隊に交通事故の通報が入りました。野菜農家の曹さんが野菜を運ぶ途中で不運にも事故に遭ったのです。幸い曹さんのけがは軽く、救急車がすぐ駆けつけて病院へ搬送しました。しかし現場には10かごもの野菜が散乱しており、早急に解決すべき課題となりました。入院中の曹さんは現場に戻れず、「たとえ傷んでいなくても翌日には売れなくなってしまう」と語りました。事故班の徐震班長は同僚と相談のうえ、野菜を整理して中隊へ運ぶことを決定。その後、中隊の警察官や補助警官たちが次々と協力を申し出て、市場価格で一人一袋ずつ残った野菜をすべて買い取りました。翌日、曹さんの妻がわざわざ中隊を訪れて「損失を随分減らしていただき本当にありがとうございます」と感謝を伝えると、警官たちは「皆暮らしは大変ですから、少しでも温かさを届けられれば」と謙虚に答えました。"}],"passageJa":"深夜、寧波市の野菜農家・曹さんが運搬中に交通事故に遭い病院へ運ばれました。現場に散乱した10かごの野菜は翌日には売れなくなる恐れがあったため、交通警察の班長と仲間たちは野菜を中隊へ運び、警察官・補助警官たちが市場価格ですべて買い取りました。翌日、曹さんの妻は中隊を訪れて心から感謝を伝えました。"},"hsk5-l2-30-32":{"id":"hsk5-l2-30-32","titleJa":"第30〜32問 共通短文（心理学の「置換理論」と習慣改善）","instructionJa":"次の短文を聞いて、第30〜32問に答えてください。","audio":{"start":1311.15,"end":1422.85},"transcript":[{"speaker":"男","text":"从心理学上讲，人们培养习惯的目的在于满足身体和心理的某种需求，而打破已有的习惯、建立一个新的习惯会破坏原有的平衡，让人不知道该怎么办。替换理论认为，习惯不可能被磨灭，只能被取代。举个例子，有的人喜欢抽烟，因为抽烟让他感到放松，可以暂时远离生活和工作的压力。如果不让他抽烟，又没有提供另外一个方法来满足他的内心需求，那么这个习惯是不容易改变的。所以，如果想要戒烟，首先要找到一种能使人放松身心的方式来替代吸烟，比如说嚼口香糖，或者可以把听音乐、运动当作替代方案。类似的，如果想戒掉垃圾食品，可以手边放一些健康的小零食，比如不含糖的饼干、酸奶等。","ja":"心理学的に見ると、人が習慣を身につける目的は心身の何らかの欲求を満たすことにあり、既存の習慣を断ち切って新しい習慣を築こうとすると元のバランスが崩れ、どうすればよいかわからなくなります。「置換理論」では、習慣は消し去ることはできず、置き換えることしかできないと考えます。例えば喫煙が好きな人は、タバコでリラックスして一時的に生活や仕事のストレスから解放されるため吸っています。禁煙させても心の欲求を満たす別の手段がなければ、習慣は容易に変わりません。ですから禁煙したければ、まずガムを噛む、音楽を聴く、運動するなど心身をリラックスさせる代替手段を見つけることが先決です。同様にジャンクフードをやめたければ、無糖ビスケットやヨーグルトなど健康的なおやつを手元に置くとよいでしょう。"}],"passageJa":"心理学の「置換理論」によれば、習慣は心身の欲求を満たすために形成されるため、消し去るのではなく良い習慣で置き換える必要があります。例えばリラックスを求めて喫煙する人が禁煙するにはガム・音楽・運動などで代替し、ジャンクフードを断つには無糖ビスケットやヨーグルトなど健康的な軽食で置き換えるのが効果的です。"},"hsk5-l2-33-35":{"id":"hsk5-l2-33-35","titleJa":"第33〜35問 共通短文（ダイエット経験を論文にした浙江大博士生）","instructionJa":"次の短文を聞いて、第33〜35問に答えてください。","audio":{"start":1438.8,"end":1553.85},"transcript":[{"speaker":"女","text":"近日，浙大光学工程专业的博士生王春程将自己的减肥经历写成了论文。论文中记录了王春程减肥路上的点点滴滴，包括身体数据、运动安排、饮食搭配，这些详细的数据都变成了论文的有力依据。在连续一个月的实践后，王春程成功瘦了六斤。在论文中，王春程像分析实验数据一样，深入分析了不同饮食搭配和锻炼频率对减肥效果的影响。王春程说：“以学术眼光去观察日常生活，能够帮助我形成学术思维，激发更多的创造力。”他将论文发布到网上后，获得了同学们的广泛关注与讨论，大家纷纷点赞留言：“能对自己有这么精确的记录和了解，真是太厉害了！”","ja":"最近、浙江大学光学工学専攻の博士課程の学生・王春程さんが、自身のダイエット経験を論文にまとめました。論文には身体データ、運動スケジュール、食事の組み合わせなどダイエット過程の詳細が記され、それらが有力な根拠となっています。1か月継続した結果、王さんは6斤（約3kg）の減量に成功。論文では実験データを分析するように、異なる食事の組み合わせや運動頻度が減量効果に与える影響を深く分析しました。王さんは「学術的な視点で日常生活を観察することは、学術的思考を養い、より多くの創造力を引き出す助けになる」と語っています。論文をネットに公開すると学生たちの間で広く注目を集め、「自分のことをこれほど精密に記録し理解できるなんて本当にすごい！」と称賛のコメントといいねが相次ぎました。"}],"passageJa":"浙江大学の博士課程の学生・王春程さんは、自身のダイエットにおける身体データ・運動計画・食事の組み合わせを詳細に記録し、1か月で6斤（約3kg）減量した成果を論文にまとめました。学術的視点で日常を見ることで学術的思考と創造力が育まれると語り、ネット上で学生たちから「すごい」と多くの称賛を集めました。"},"hsk5-r1-36-38":{"id":"hsk5-r1-36-38","titleJa":"第36〜38問 共通短文（文文の「お給料」）","instructionJa":"次の短文を読み、空欄【36】〜【38】に入る最も適切な語句を選んでください。","passageZh":"四岁的文文跟妈妈去看望外公，文文骄傲地说：“外公，我在幼儿园能自己穿衣服，不需要老师帮忙了。”外公听了高兴地称赞道：“外孙女真【36】，外公必须得奖励你。”于是，他包了一个红包给文文。文文把红包【37】给了妈妈，说：“请把我的工资收好。”妈妈笑问：“你才四岁，又不上班，【38】？”文文委屈地说：“我怎么没有上班？我不是正在幼儿园上小班吗？”","passageJa":"4歳の文文（ウェンウェン）は母親とおじいちゃんを訪ね、得意げに「おじいちゃん、幼稚園で先生の手を借りずに自分で服を着られるようになったよ」と言いました。おじいちゃんは喜んで「孫娘は本当にすごいね（36）、ご褒美をあげなくちゃ」と褒め、お年玉袋（紅包）を包んで渡しました。文文はその紅包を母親に手渡し（37）、「私のお給料をしまっておいて」と言いました。母親が笑いながら「まだ4歳で仕事にも行っていないのに、なんと給料までもらうようになったの？（38）」と尋ねると、文文は悔しそうに「どうして仕事（上班）してないの？私、幼稚園の年少組に通っている（上小班）じゃない！」と言いました。"},"hsk5-r1-39-41":{"id":"hsk5-r1-39-41","titleJa":"第39〜41問 共通短文（古代技術典籍『考工記』）","instructionJa":"次の短文を読み、空欄【39】〜【41】に入る最も適切な語句を選んでください。","passageZh":"《考工记》是中国到目前为止发现的年代最早的一部手工技术与工艺典籍。全书7000多字，篇幅并不长，【39】。该书记载了木工、金工、皮革、染色、刮磨、陶瓷等六大类三十个工种的内容，【40】了当时中国所达到的科技及工艺水平。此外，书中还总结了数学、力学、声学、地理学、建筑学等多方面的知识和经验。《考工记》在中国科技史、工艺美术史和文化史上都占有重要【41】。","passageJa":"『考工記』は中国でこれまでに発見された最古の手工技術・工芸に関する典籍である。全書7,000字あまりで分量自体は長くないが、内容は非常に豊富だ（39）。本書には木工・金工・皮革・染色・研磨・陶磁など6大分類30職種の内容が記されており、当時の中国が到達していた科学技術・工芸水準を反映している（40）。さらに数学・力学・音響学・地理学・建築学など多方面の知識と経験もまとめられている。『考工記』は中国の科学技術史・工芸美術史・文化史において重要な地位を占めている（41）。"},"hsk5-r1-42-45":{"id":"hsk5-r1-42-45","titleJa":"第42〜45問 共通短文（中国で愛される電動自転車）","instructionJa":"次の短文を読み、空欄【42】〜【45】に入る最も適切な語句を選んでください。","passageZh":"近年来，中国电动自行车年销量超过三千万辆，社会现有电动自行车数量接近三亿辆，相当于几乎每个家庭都有一辆电动自行车。为什么人们对电动自行车这么“情有独钟”？\\n\\n首先是方便。【42】，电动自行车在启动和停车时花费的时间最少。随着智能化程度的加深，电动自行车甚至不再需要使用钥匙，直接用手机开锁就行，再加上占地【43】小，车主也不再为找车位而发愁。\\n\\n其次是用途【44】。电动自行车的使用体验好，适用于多种日常生活场景：上下班、接送孩子、外出买菜……也不用考取驾照，上了年纪的人也可以驾驶，能【45】多方面需求。","passageJa":"近年、中国の電動自転車の年間販売台数は3,000万台を超え、社会全体の保有台数は3億台近くに達しており、ほぼすべての家庭に1台ある計算になる。なぜ人々は電動自転車をこれほど特別に好むのだろうか？\\n\\n第一に便利さである。他の交通手段と比べて（42）、電動自転車は発進と駐車にかかる時間が最も短い。スマート化が進むにつれ鍵すら不要になり、スマホでそのまま解錠できるうえ、占有面積（43）も小さいため、駐車場所探しに悩むこともない。\\n\\n第二に用途が広いこと（44）である。使い心地が良く、通勤・子どもの送迎・買い物など多様な日常シーンに適している。運転免許も不要で高齢者も運転でき、多方面のニーズを満たす（45）ことができる。"},"hsk5-r2-46-50":{"id":"hsk5-r2-46-50","titleJa":"第46〜50問 段落並べ替え（大学履修登録のお知らせ）","instructionJa":"下の5つの段落（A〜E）を論理・手順に沿って並べ替え、1番目（第46問）〜5番目（第50問）に入る段落を選んでください。","bankOptions":[{"label":"A","text":"请同学们务必在两轮选课期间办理选课、退课，超时将不能办理，如对平台操作有疑问，请联系教务处。","meaningJa":"学生の皆さんは必ず2回の履修登録期間内に登録・取消の手続きを行ってください。期限を過ぎると手続きできません。システム操作に疑問があれば教務課へ連絡してください。"},{"label":"B","text":"此计划中明确写出了毕业所需达到的学分要求，是选课的重要参考依据。","meaningJa":"この計画書には卒業に必要な単位要件が明記されており、履修選択の重要な参考基準となります。"},{"label":"C","text":"我校2024～2025学年第二学期第一轮选课将于2025年1月1日12:00开始，至2025年1月8日12:00结束。选课前请各位同学提前查看本专业教学计划。","meaningJa":"本学2024〜2025年度第2学期の第1次履修登録は、2025年1月1日12:00から1月8日12:00まで実施します。登録前に各自所属専攻のカリキュラム計画を事前に確認してください。"},{"label":"D","text":"1月8日选课结束后，课程未达到开班人数的会停开，选修停开课程的同学及还未选课的同学，可于1月10日至13日参加第二轮选课。","meaningJa":"1月8日の登録終了後、開講定員に満たない科目は開講中止となります。中止科目を選んでいた学生および未登録の学生は、1月10日〜13日の第2次履修登録に参加できます。"},{"label":"E","text":"在了解教学计划规定的要求后，同学们可以在选课期间根据自己的时间、兴趣及专业要求进入“本科教学管理与服务”平台进行选课。","meaningJa":"カリキュラム計画の要件を把握したうえで、学生は登録期間中に自分の時間割・興味・専攻要件に応じて「学部教学管理・サービス」プラットフォームへ入り履修登録を行えます。"}],"passageJa":"【正しい順序：C → B → E → D → A】\\n①(C) 本学2024〜2025年度第2学期の第1次履修登録は2025年1月1日12:00〜1月8日12:00です。登録前に所属専攻の教学計画を確認してください。\\n②(B) この計画には卒業必要単位が明記されており、履修選択の重要な根拠となります。\\n③(E) 教学計画の要件を理解した後、登録期間中にプラットフォームへ入って履修登録できます。\\n④(D) 1月8日の登録終了後、定員未達の科目は閉講となり、該当者や未登録者は1月10日〜13日に第2次登録に参加できます。\\n⑤(A) 必ず2回の期間内に登録・取消を行ってください。操作に疑問があれば教務課まで。"},"hsk5-r2-51-55":{"id":"hsk5-r2-51-55","titleJa":"第51〜55問 段落並べ替え（王勃の送別詩『送杜少府之任蜀州』）","instructionJa":"下の5つの段落（A〜E）を物語の流れに沿って並べ替え、1番目（第51問）〜5番目（第55問）に入る段落を選んでください。","bankOptions":[{"label":"A","text":"一天，王勃像平常一样去找这位朋友，可是一进门，却见到朋友沉默地坐在椅子上，一副难过的样子。","meaningJa":"ある日、王勃がいつものようにこの友人を訪ねると、部屋に入るなり友人が黙って椅子に座り、悲しそうな様子をしているのを目にした。"},{"label":"B","text":"这首诗的第三句非常经典：海内存知己，天涯若比邻，意思是：只要是知心的朋友，即使距离再远，也感觉像在身边一样。这句诗流传千年，至今仍然被人们用来表达友情。","meaningJa":"この詩の第三句「海内存知己，天涯若比邻」は非常に名高い。心の通じ合う友であれば、どれほど遠く離れていても隣にいるように感じられるという意味である。この句は千年にわたり伝えられ、今日でも友情を表す言葉として用いられている。"},{"label":"C","text":"王勃是中国古代的著名文学家。他在长安时，交到了一位姓杜的朋友。两人关系密切，经常一起游玩、写诗。","meaningJa":"王勃は中国古代の著名な文学者である。彼は長安にいたころ、杜という姓の友人と親交を結んだ。二人は親密で、よく一緒に遊んだり詩を作ったりしていた。"},{"label":"D","text":"日子过得很快，转眼朋友就要离开长安了。两人告别前，王勃回忆起和朋友相处时的种种趣事，心中十分不舍。于是，他为朋友写了一首送别诗，名为《送杜少府之任蜀州》。","meaningJa":"月日はあっという間に過ぎ、まもなく友人が長安を去る日となった。別れを前に、王勃は友人と過ごした数々の楽しい出来事を思い出し、名残惜しさでいっぱいになった。そこで友人のために『送杜少府之任蜀州』という送別詩を詠んだ。"},{"label":"E","text":"王勃连忙询问朋友发生了什么事，朋友告诉他：自己被朝廷派去蜀州做官，再过几天就要出发了。蜀州偏远，他并不想去那儿，因此心情很糟糕。王勃听到这个消息，也感到非常难过。","meaningJa":"王勃が慌てて何があったのか尋ねると、友人は「朝廷から蜀州の官職を命じられ、数日後に出発しなければならない」と告げた。蜀州は辺鄙で気が進まず落ち込んでいたのだ。王勃もその知らせを聞いてひどく悲しんだ。"}],"passageJa":"【正しい順序：C → A → E → D → B】\\n①(C) 王勃は中国古代の著名な文学者で、長安で杜姓の友人と親しくし、よく一緒に遊んで詩を作った。\\n②(A) ある日いつものようにこの友人を訪ねると、友人は黙って椅子に座り悲しそうだった。\\n③(E) 慌てて理由を尋ねると、辺鄙な蜀州へ赴任を命じられ数日後に旅立つという。王勃も悲しんだ。\\n④(D) まもなく別れの日が来て、王勃は名残惜しさから『送杜少府之任蜀州』という送別詩を贈った。\\n⑤(B) この詩の名句「海内存知己，天涯若比邻」は千年を経た今も友情を表す言葉として愛されている。"},"hsk5-r3-56-58":{"id":"hsk5-r3-56-58","titleJa":"第56〜58問 共通長文（移動理髪店でボランティアを続ける孫凱）","instructionJa":"次の文章を読み、第56〜58問に答えてください。","passageImage":"./images/hsk5/R3_56_58.jpg","passageImageAlt":"高齢男性の髪をくしで整えながら丁寧に理髪している理髪師の様子","passageZh":"38岁的孙凯从事理发行业已经二十年，如今在繁华的王府井地区经营着一家高端理发店。他一直热心志愿服务，常上门为行动不便的老人免费理发。\\n\\n为了方便上门服务，他把行李箱改成了简单的“移动理发店”——里面不仅有各种理发工具和理发镜，理发镜旁边还安装了音箱。孙凯希望音乐可以给顾客带来些许乐趣。为了帮助更多老人，他组织成立了“梵珀匠人志愿服务队”，四年来，这支志愿服务队已累计为五百多位老人义务理发。\\n\\n孙凯对自己的工作和志愿服务事业有着自己的想法。“我希望做一名‘有爱又有才’的理发师。”孙凯说，“‘爱’是指志愿服务，‘才’是指技能进步。”他说，做好服务只靠爱心是不够的，过硬的技术才是服务的基础。他打算平时再多下点儿功夫，提升技术水平，把志愿服务长久地做下去。","passageJa":"38歳の孫凱さんは理容業界に携わって20年になり、現在は賑やかな王府井エリアで高級理髪店を経営している。彼はかねてからボランティア活動に熱心で、外出が困難な高齢者の自宅を訪問して無料で散髪を行っている。\\n\\n訪問サービスを便利にするため、彼はスーツケースを簡易的な「移動理髪店」に改造した。中には各種理髪道具と鏡が入っているだけでなく、鏡の横にはスピーカーまで取り付けられている。音楽が利用客にささやかな楽しみをもたらしてほしいという願いからだ。さらに多くの高齢者を助けるため「梵珀匠人ボランティアサービス隊」を結成し、4年間で延べ500人以上の高齢者に無料散髪を行ってきた。\\n\\n孫凱さんは仕事とボランティアについて独自の考えを持っている。「『愛があり才もある』理髪師になりたい」と語り、「『愛』はボランティア、『才』は技術の向上を指す」と言う。良いサービスは思いやりだけでは不十分で、確かな技術こそが土台であると考え、普段からさらに努力を重ねて技術水準を高め、ボランティアを長く続けていく予定だ。"},"hsk5-r3-59-62":{"id":"hsk5-r3-59-62","titleJa":"第59〜62問 共通長文（中国教育界「工程画の第一人者」施岳定）","instructionJa":"次の文章を読み、第59〜62問に答えてください。","passageImage":"./images/hsk5/R3_59_62.jpg","passageImageAlt":"複雑な構造を持つ自動車エンジンの精密なクローズアップ写真","passageZh":"浙江大学工程学院院史馆内，一幅标题为“发动机剖视”的教学挂图引起了众多参观者关注。画中发动机的内部结构、材料特征等，几乎和真的一样，甚至还带着几分“动感”。\\n\\n这幅挂图是由浙江大学工程学院教师施岳定创作的。在20世纪80年代初，施岳定就开始在教学中运用自己的挂图了。\\n\\n施岳定在长期教学实践中发现，由于缺乏直接观察的经验，学生们常常难以理解复杂机器的工作原理、结构间的安装关系。“比如每次讲到汽车、内燃机等复杂结构的时候，我们没法儿把汽车开进教室，又不能拆开设备，给学生看里面的详细结构。”而国内当时教材中的教学挂图又不能清楚明确地表现复杂机器的结构，于是施岳定产生了一个想法——把这些复杂机器结构用立体画的方式展示出来。\\n\\n那幅《发动机剖视》图，施岳定画了整整三个月。凭借对教育事业的热爱，他白天上课、搞科研，晚上集中精力画图。施岳定陆续画了百余幅这样的课堂挂图，其中许多图片成为了教材插图，帮助了许多学生。正因如此，他被称为中国教育界的“工程画第一人”。","passageJa":"浙江大学工学院の院史館では、『エンジン断面図（发动机剖视）』と題された教育用掛図が多くの来館者の注目を集めている。絵の中のエンジン内部構造や材質の特徴は本物そっくりで、躍動感さえ帯びている。\\n\\nこの掛図は浙江大学工学院の教員・施岳定氏が制作したものだ。1980年代初頭から、施氏は授業で自作の掛図を活用し始めていた。\\n\\n施氏は長年の教育実践の中で、直接観察する経験が乏しいため学生が複雑な機械の作動原理や部品の組み付け関係を理解しにくいことに気づいた。「例えば自動車や内燃機関のような複雑な構造を説明するとき、教室に車を持ち込むことも機器を分解して中を見せることもできない」。しかも当時の国内教材の掛図は複雑な機械構造を明瞭に表せていなかったため、施氏はそれらを立体画で表現しようと思い立ったのだ。\\n\\n『エンジン断面図』は丸3か月かけて描き上げた。教育への情熱を支えに、昼は授業と研究に励み、夜は作図に没頭した。こうして100点余りの授業用掛図を描き続け、その多くが教科書の挿絵に採用されて大勢の学生を助けた。まさにそれゆえ、彼は中国教育界の「工程画第一人者」と呼ばれている。"},"hsk5-r3-63-66":{"id":"hsk5-r3-63-66","titleJa":"第63〜66問 共通長文（桑国亜と中国茶文化の広がり）","instructionJa":"次の文章を読み、第63〜66問に答えてください。","passageImage":"./images/hsk5/R3_63_66.jpg","passageImageAlt":"竹のマットの上に置かれた紫砂の急須、茶葉、4つの湯呑みによる中国茶器セット","passageZh":"1991年，桑国亚只身一人来到中国留学。随着在中国的时间越来越长，桑国亚对茶的兴趣越来越浓，认识也越来越深刻。他说，中国的茶文化总让他感觉“学而知不足”。\\n\\n为了进一步增进了解，桑国亚开始正式学习茶艺，他走遍了中国各地茶园，“在福建，每天晚饭后在家中泡上一壶铁观音，成为当地家庭生活的一部分；在广州，茶楼里的茶艺师傅摆弄着各式各样的茶具，表演着精彩的工夫茶；在成都，朋友邀请我去茶馆品尝竹叶青，让我第一次看到茶叶直直地立在水中。”桑国亚说，这些经历不仅让他收获了与茶相关的知识，还认识了很多热情好客的中国朋友。\\n\\n如今，对茶的热爱让桑国亚开始向更多的人分享中国茶文化。他回国后在学校里教茶文化课，在他的课堂上，有人对茶的种类、饮茶方法等感兴趣；有人则因喝茶有益健康而渴望了解茶。\\n\\n桑国亚发现，陷入烦恼时，泡一杯茶细细品味能让人忘记那些令人头疼的问题。“需要提神选绿茶，需要暖胃选红茶。”桑国亚希望通过自己的努力，把茶的趣味分享给更多的人。","passageJa":"1991年、桑国亜さんは単身で中国へ留学した。滞在が長くなるにつれ、茶への興味はますます深まり理解も深まった。中国の茶文化はいつも自分に「学べば学ぶほど自分の不足を知る（学而知不足）」と感じさせると彼は語る。\\n\\n理解をさらに深めるため、桑さんは本格的に茶芸を学び中国各地の茶園を巡った。「福建では毎晩の食後に家で鉄観音を淹れるのが家庭生活の一部になっており、広州では茶楼の茶芸師が多彩な茶器を操って見事な工夫茶を披露し、成都では友人に誘われた茶館で竹葉青を味わい、茶葉が水中で真っ直ぐ立つ様子を初めて見た」と語る。これらの経験は茶の知識だけでなく、親切な中国の友人たちとの出会いももたらした。\\n\\n現在、茶への愛から桑さんはより多くの人に中国茶文化を伝えている。帰国後は学校で茶文化の授業を担当しており、茶の種類や淹れ方に興味を持つ生徒もいれば、健康効果を期待して学びたがる生徒もいる。\\n\\n桑さんは、悩みを抱えたときに一杯のお茶をじっくり味わうと頭の痛い問題を忘れられることに気づいた。「目を覚ましたいときは緑茶、胃を温めたいときは紅茶」と語り、自らの努力でお茶の楽しさをより多くの人へ分かち合いたいと願っている。"},"hsk5-r3-67-70":{"id":"hsk5-r3-67-70","titleJa":"第67〜70問 共通長文（紅山森林動物園の「動物里親（認養）」制度）","instructionJa":"次の文章を読み、第67〜70問に答えてください。","passageImage":"./images/hsk5/R3_67_70.jpg","passageImageAlt":"木の幹の上で緑の葉に囲まれながら愛らしく顔をのぞかせるレッサーパンダ","passageZh":"红山森林动物园位于江苏省南京市，跟中国其他动物园不同，这家动物园不依靠政府，完全独立经营，所以动物园的经营状况对其生存发展至关重要。为了增加收入，红山森林动物园设有动物认养活动，支付一定的养护费用后，人们可以认领自己喜欢的动物。\\n\\n目前有线下认养和“云认养”两种方式。线下认养早在2001年就已经开展，线下认养人每年可以进入场馆深度体验一次，可以帮忙打扫卫生，了解饲养员日常如何照顾动物，还可以参加“动物馆奇妙夜”等科普教育活动。随着线上认养需求的增加，2021年动物园开通了“云认养”方式，主要针对无法到场馆实地参观的游客。线上认养人可以通过每月一次的点对点直播，观看到自己认养的小动物。这样，在给予大家精神陪伴的同时，动物园也拓宽了经济来源，可以说是双赢。\\n\\n据工作人员介绍，目前已有一百五十只左右的动物被认养，对园区来说，这不仅改善了园区的经济状况，更重要的是加强了动物园和公众之间的联结，通过这种深度的体验方式让更多人关注、支持野生动物保护。","passageJa":"紅山森林動物園は江蘇省南京市にあり、中国の他の動物園とは異なって政府に依存せず完全独立採算で運営されているため、経営状況がその存続と発展にとって極めて重要である。収入を増やすため、同園は動物認養（里親スポンサー）制度を設けており、一定の飼育費を支払えば好きな動物の里親になることができる。\\n\\n現在はオフライン認養と「クラウド（雲）認養」の2種類がある。オフライン認養は2001年から実施されており、里親は年1回獣舎へ入ってディープな体験ができ、掃除を手伝ったり飼育員の日常ケアを学んだり、「動物園の不思議な夜」などの科学教育イベントにも参加できる。オンライン需要の増加に伴い2021年に開設された「クラウド認養」は、主に現地へ来られない人々向けで、月1回の個別ライブ配信を通じて自分の認養動物を見ることができる。こうして人々に心の癒しを提供しつつ動物園も収益源を広げ、まさにウィンウィンと言える。\\n\\nスタッフによると現在約150頭の動物が認養されており、園にとっては経済状況の改善だけでなく、動物園と市民の絆を強め、こうした深い体験を通じてより多くの人が野生動物保護に関心を持ち支援するきっかけになることがより重要だという。"}}'),n=JSON.parse('[{"id":1,"section":"listening","partId":"L1","kind":"mcq","options":[{"label":"A","text":"旅游意外险","meaningJa":"旅行傷害保険"},{"label":"B","text":"重大疾病险","meaningJa":"重大疾病保険"},{"label":"C","text":"补充养老保险","meaningJa":"補足年金保険"},{"label":"D","text":"基本医疗保险","meaningJa":"基本医療保険"}],"answer":"B","audio":{"start":71.55,"end":94.8},"transcript":[{"speaker":"女","text":"您好，我想给我父亲买一份商业保险。","ja":"こんにちは、父のために民間の商業保険に入りたいのですが。"},{"speaker":"男","text":"您父亲多大年纪了？有基础疾病吗？","ja":"お父様はおいくつですか？持病（基礎疾患）はおありですか？"},{"speaker":"女","text":"他62了，身体还行，就是有高血压。","ja":"62歳で体はまずまずですが、高血圧があるんです。"},{"speaker":"男","text":"我建议您选择重大疾病险，作为基本医疗保险的补充。","ja":"基本医療保険の補足として、重大疾病保険をお選びになることをお勧めします。"},{"speaker":"问","text":"男的推荐了哪个产品？","ja":"男性はどの商品を勧めましたか？"}],"translationJa":"女：父に商業保険を買いたいのですが。\\n男：お父様は何歳で、持病はありますか？\\n女：62歳で体はまずまずですが高血圧があります。\\n男：基本医療保険の補足として、重大疾病保険をお勧めします。\\n【質問】男性はどの商品を勧めましたか？","explanationJa":"男性は最後に「我建议您选择重大疾病险，作为基本医疗保险的补充（基本医療保険の補足として重大疾病保険を選ぶことをお勧めします）」と明言しているため、正解は B です。","tipJa":"「作为〜的补充（〜の補足として）」に引っかかって D（基本医疗保险）を選ばないよう注意！「建议选择〜」の直後の目的語をしっかり聞き取りましょう。「基础疾病（基礎疾患・持病）」も現代の頻出語彙です。"},{"id":2,"section":"listening","partId":"L1","kind":"mcq","options":[{"label":"A","text":"现场排队购票","meaningJa":"現地で並んでチケットを買う"},{"label":"B","text":"自觉接受安检","meaningJa":"進んで保安検査を受ける"},{"label":"C","text":"进行电话预订","meaningJa":"電話で予約する"},{"label":"D","text":"提前线上预约","meaningJa":"事前にオンライン予約する"}],"answer":"D","audio":{"start":109.65,"end":133.85},"transcript":[{"speaker":"男","text":"国庆节我想去参观国家博物馆，要提前买门票吗？","ja":"国慶節に国家博物館を見学したいのですが、事前にチケットを買う必要がありますか？"},{"speaker":"女","text":"不用，那儿免费开放，但一定要先在线上预约。","ja":"いいえ、あそこは無料開放されています。でも必ず先にオンライン予約をしないといけませんよ。"},{"speaker":"男","text":"具体怎么弄？","ja":"具体的にはどうやるのですか？"},{"speaker":"女","text":"在手机上搜索“国家博物馆”小程序，点进去根据提示操作就行。","ja":"スマホで「国家博物館」のミニプログラムを検索し、開いて案内に従って操作すれば大丈夫です。"},{"speaker":"问","text":"女的提醒男的怎么做？","ja":"女性は男性にどうするよう注意喚起しましたか？"}],"translationJa":"男：国慶節に国家博物館へ行きたいのですが、事前にチケットが必要ですか？\\n女：無料開放なので不要ですが、必ず先にオンライン予約をしてください。\\n男：具体的にはどうすれば？\\n女：スマホで「国家博物館」ミニプログラムを検索し、案内に沿って操作すればOKです。\\n【質問】女性は男性にどうするよう促しましたか？","explanationJa":"女性が「但一定要先在线上预约（ただし必ず先にオンライン予約をしてください）」と強調しており、D「提前线上预约」と完全に一致します。","tipJa":"「但一定要〜（しかし必ず〜しなければならない）」の逆接の後に核心情報が来ます。「小程序（ミニプログラム）」は WeChat などのアプリ内アプリを指す中国生活の定番語彙です。"},{"id":3,"section":"listening","partId":"L1","kind":"mcq","options":[{"label":"A","text":"花费更高","meaningJa":"費用がより高い"},{"label":"B","text":"讲究细节","meaningJa":"細部にこだわる"},{"label":"C","text":"很难执行","meaningJa":"実行がとても難しい"},{"label":"D","text":"风格多样","meaningJa":"スタイルが多様である"}],"answer":"A","audio":{"start":148.9,"end":173.5},"transcript":[{"speaker":"女","text":"这几套装修方案您觉得怎么样？","ja":"こちらのいくつかの内装プランはいかがでしょうか？"},{"speaker":"男","text":"第二套不错，我们夫妇俩都喜欢中式风格。","ja":"2番目のプランがいいですね。私たち夫婦は二人とも中華風スタイルが好きなので。"},{"speaker":"女","text":"那家具和装饰材料会以实木为主，整体成本也更高一些。","ja":"それですと家具や装飾材は無垢材が中心になり、全体のコストも少し高くなります。"},{"speaker":"男","text":"明白，帮我们估算一下价格吧。","ja":"わかりました。価格を見積もってください。"},{"speaker":"问","text":"关于第二套装修方案，可以知道什么？","ja":"2番目の内装プランについて何がわかりますか？"}],"translationJa":"女：これらの内装プランはいかがですか？\\n男：2番目がいいですね、夫婦とも中華風が好きなので。\\n女：家具や内装材が無垢材中心になり、全体のコストも高めになります。\\n男：了解です、見積もりを出してください。\\n【質問】2番目の内装プランについて何がわかりますか？","explanationJa":"女性が第2プランについて「整体成本也更高一些（全体のコストもより高い）」と説明しており、「成本更高」を言い換えた A「花费更高」が正解です。","tipJa":"HSK5級では「成本（コスト）」→「花费（費用）」のような同義語パラフレーズが頻出します。「实木（無垢材）」「估算（見積もる）」も合わせて覚えましょう。"},{"id":4,"section":"listening","partId":"L1","kind":"mcq","options":[{"label":"A","text":"国内公司的待遇","meaningJa":"国内企業の待遇"},{"label":"B","text":"留学生就业选择","meaningJa":"留学生の就職先の選択"},{"label":"C","text":"如何让简历更出色","meaningJa":"履歴書をより良くする方法"},{"label":"D","text":"毕业生学历统计数据","meaningJa":"卒業生の学歴統計データ"}],"answer":"B","audio":{"start":188.65,"end":211.7},"transcript":[{"speaker":"男","text":"新闻里说，今年84%的留学生毕业后选择回国，比例又上升了。","ja":"ニュースによると、今年84％の留学生が卒業後に帰国を選んでいて、割合がまた上がったそうだよ。"},{"speaker":"女","text":"毕竟现在国内发展迅速，就业机会更多。","ja":"何と言っても今は国内の発展が速くて、就職のチャンスがより多いからね。"},{"speaker":"男","text":"那咱们也要提前做好准备。","ja":"じゃあ僕たちも早めに準備しておかないとね。"},{"speaker":"女","text":"嗯，我这段时间就在往国内的几家公司投简历呢。","ja":"うん、私もこのところ国内のいくつかの企業に履歴書を送っているところなの。"},{"speaker":"问","text":"他们在聊什么？","ja":"二人は何について話していますか？"}],"translationJa":"男：ニュースで今年84％の留学生が卒業後帰国すると言っていたよ。\\n女：国内の発展が速く就職機会が多いからね。\\n男：じゃあ僕らも早めに準備しよう。\\n女：うん、最近国内の企業数社に履歴書を送っているの。\\n【質問】二人は何について話していますか？","explanationJa":"留学生の多くが卒業後に帰国して国内企業へ就職する傾向や、自分たちの就活準備について話しているため、B「留学生就业选择」が全体の主題として最適です。","tipJa":"「投简历（履歴書を送る）」や「84%」といった部分的な語句に釣られて C や D を選ばず、対話全体のテーマを俯瞰しましょう。"},{"id":5,"section":"listening","partId":"L1","kind":"mcq","options":[{"label":"A","text":"墙面更平整","meaningJa":"壁面がより平らになった"},{"label":"B","text":"设施更完善","meaningJa":"設備がより整った"},{"label":"C","text":"更加现代化","meaningJa":"より現代的になった"},{"label":"D","text":"居民变少了","meaningJa":"住民が減った"}],"answer":"C","audio":{"start":226.55,"end":253.05},"transcript":[{"speaker":"女","text":"小时候我就住在这条胡同里，这儿的一砖一瓦都有上百年的历史了。","ja":"小さいころこの胡同に住んでいたの。ここのレンガ一つ瓦一つに百年以上の歴史があるのよ。"},{"speaker":"男","text":"这次回来感觉怎么样？","ja":"今回戻ってきてみてどう感じる？"},{"speaker":"女","text":"既亲切又陌生，没想到新开了这么多餐厅和工作室，更现代了。","ja":"懐かしくもあり見慣れない感じもするわ。こんなにたくさんのレストランやアトリエが新しくできて、より現代的になったなんて思わなかった。"},{"speaker":"男","text":"是啊，老胡同也变年轻了。","ja":"そうだね、古い胡同も若返ったね。"},{"speaker":"问","text":"女的觉得胡同有什么变化？","ja":"女性は胡同にどんな変化があったと感じていますか？"}],"translationJa":"女：幼いころ住んでいたこの胡同は百年以上の歴史があるの。\\n男：戻ってきてどう？\\n女：懐かしくも新鮮で、レストランやスタジオが増えてより現代的になったわ。\\n男：そうだね、古い胡同も若返ったね。\\n【質問】女性は胡同にどんな変化があったと感じていますか？","explanationJa":"女性が「没想到新开了这么多餐厅和工作室，更现代了（レストランやスタジオが多くできて、より現代的になった）」と述べているため、C「更加现代化」が正解です。","tipJa":"「一砖一瓦（レンガ一つ瓦一つ）」は歴史ある街並みを表す表現。「既A又B（AでもありBでもある）」の構文もしっかり押さえましょう。"},{"id":6,"section":"listening","partId":"L1","kind":"mcq","options":[{"label":"A","text":"上网咨询","meaningJa":"ネットで相談する"},{"label":"B","text":"询问物业","meaningJa":"管理会社に問い合わせる"},{"label":"C","text":"检查水管","meaningJa":"水道管を点検する"},{"label":"D","text":"给邻居留言","meaningJa":"隣人にメモを残す"}],"answer":"B","audio":{"start":267.85,"end":289.1},"transcript":[{"speaker":"男","text":"你快来看看，屋顶怎么在滴水？","ja":"ちょっと早く見に来て、天井からなんで水が垂れてるんだ？"},{"speaker":"女","text":"还真是，沙发都湿了，可能是管道漏水了，我去楼上问问。","ja":"本当だわ、ソファまで濡れちゃってる。配管の水漏れかも、上の階へ聞きに行ってくるわ。"},{"speaker":"男","text":"你忘了，咱们楼上没住人。","ja":"忘れたのかい？うちの上の階は誰も住んでないよ。"},{"speaker":"女","text":"那赶快联系一下物业吧。","ja":"じゃあ急いで管理会社（物業）に連絡しましょう。"},{"speaker":"问","text":"他们接下来最可能做什么？","ja":"二人はこの後何をする可能性が最も高いですか？"}],"translationJa":"男：ちょっと見て、天井から水漏れしてるよ。\\n女：本当、ソファが濡れてる。配管漏れかも、上の階に聞いてくる。\\n男：上の階は空き家だよ。\\n女：じゃあ急いで管理会社に連絡しよう。\\n【質問】二人はこの後何をする可能性が最も高いですか？","explanationJa":"上の階に人が住んでいないとわかり、女性が最後に「那赶快联系一下物业吧（じゃあ早く管理会社に連絡しよう）」と結論づけているため、B「询问物业」が正解です。","tipJa":"「物业（マンション・団地の管理会社／管理組合）」はHSK5級の生活会話で非常によく出ます。最後のターンの提案がそのまま答えになる典型パターンです。"},{"id":7,"section":"listening","partId":"L1","kind":"mcq","options":[{"label":"A","text":"味道极其苦","meaningJa":"味が極めて苦い"},{"label":"B","text":"需要长期食用","meaningJa":"長期的に食べる必要がある"},{"label":"C","text":"属于销售手段","meaningJa":"販売手法の一つである"},{"label":"D","text":"容易消化吸收","meaningJa":"消化吸収しやすい"}],"answer":"C","audio":{"start":304.05,"end":327.1},"transcript":[{"speaker":"女","text":"昨天我在面包店买了一款中药面包。","ja":"昨日パン屋さんで「漢方パン」を買ったのよ。"},{"speaker":"男","text":"中药面包？听起来可不太好吃。","ja":"漢方パン？聞いた感じあまり美味しくなさそうだけど。"},{"speaker":"女","text":"说是一种创新做法，其实味道和普通面包差不多。","ja":"新しいアイデアの商品だそうだけど、実は味は普通のパンとほとんど同じなの。"},{"speaker":"男","text":"我感觉这就是一种商家吸引顾客的销售手段。","ja":"それって店が客を引きつけるための販売手法（マーケティング戦略）って感じがするね。"},{"speaker":"问","text":"男的怎么看那种面包？","ja":"男性はそのパンをどう見ていますか？"}],"translationJa":"女：昨日パン屋で漢方パンを買ったの。\\n男：漢方パン？あまり美味しくなさそうだけど。\\n女：斬新な製法らしいけど味は普通のパンとほぼ同じよ。\\n男：店が客を引くための販売手法だと思うな。\\n【質問】男性はそのパンをどう見ていますか？","explanationJa":"男性は「我感觉这就是一种商家吸引顾客的销售手段（店が客を引くための販売手法だと感じる）」と述べているため、C「属于销售手段」が正解です。","tipJa":"「中药」という単語のイメージだけで A（苦い）や B（長期服用）を選ばないように！「我感觉〜」の後に話し手の意見が直接述べられます。"},{"id":8,"section":"listening","partId":"L1","kind":"mcq","options":[{"label":"A","text":"付款方式","meaningJa":"支払い方法"},{"label":"B","text":"当前物价","meaningJa":"現在の物価"},{"label":"C","text":"商品运费","meaningJa":"商品の送料"},{"label":"D","text":"交易押金","meaningJa":"取引の保証金"}],"answer":"A","audio":{"start":342,"end":366.4},"transcript":[{"speaker":"男","text":"奇怪，我这笔订单怎么显示付款0元？","ja":"おかしいな、この注文どうして支払額0元って表示されてるんだろう？"},{"speaker":"女","text":"你可能使用了“先用后付”功能，确认收货后会自动付款。","ja":"たぶん「先用後付（後払い）」機能を使ったのよ。受取確認をすると自動で引き落とされるの。"},{"speaker":"男","text":"居然还能这样，现在买东西真方便。","ja":"そんなことまでできるんだ、今の買い物は本当に便利だな。"},{"speaker":"女","text":"确实，但也容易让人过度消费，还是要谨慎使用。","ja":"確かにね。でも使いすぎやすいから、慎重に使ったほうがいいわよ。"},{"speaker":"问","text":"男的对什么感到吃惊？","ja":"男性は何に対して驚いていますか？"}],"translationJa":"男：変だな、この注文の支払額が0元になってる。\\n女：「先用後付（受け取り後自動決済）」機能を使ったのかも。\\n男：そんなことができるなんて、今の買い物は便利だね。\\n女：そうね、でも過剰消費しやすいから慎重にね。\\n【質問】男性は何に驚いていますか？","explanationJa":"「先用后付（先に使って後で支払う）」という決済機能の説明を聞き、男性が「居然还能这样（まさかそんなことまでできるとは）」と驚いているため、A「付款方式」が正解です。","tipJa":"「居然（なんと・まさか）」は驚きを表す超重要副詞！設問の「感到吃惊（驚く）」と直結する合図です。「一笔订单（1件の注文）」の量詞「笔」も覚えましょう。"},{"id":9,"section":"listening","partId":"L1","kind":"mcq","options":[{"label":"A","text":"特色美食","meaningJa":"ご当地グルメ"},{"label":"B","text":"传统节日","meaningJa":"伝統的な祝日"},{"label":"C","text":"手工艺品","meaningJa":"手工芸品"},{"label":"D","text":"民族服装","meaningJa":"民族衣装"}],"answer":"D","audio":{"start":381.35,"end":403.45},"transcript":[{"speaker":"女","text":"学校要举办一个关于中国各民族服装的讲座。","ja":"学校で中国の少数民族の衣装に関する講座が開かれるそうよ。"},{"speaker":"男","text":"我正好想了解一下，感觉他们的服装都很独特。","ja":"ちょうど知りたいと思っていたんだ。どの民族の衣装も個性的だよね。"},{"speaker":"女","text":"据说讲座当天，观众还有机会试穿呢。","ja":"講座当日は来場者が試着できるチャンスもあるんですって。"},{"speaker":"男","text":"太好了，我们到时候一起去。","ja":"それはいいね、当日一緒に行こう。"},{"speaker":"问","text":"下列哪项是讲座的主题？","ja":"次のうちどれが講座のテーマですか？"}],"translationJa":"女：学校で中国の各民族衣装についての講座が開かれるのよ。\\n男：ちょうど知りたかったんだ、どれも独特だよね。\\n女：当日は試着の機会もあるらしいわ。\\n男：いいね、一緒に行こう。\\n【質問】次のうちどれが講座のテーマですか？","explanationJa":"冒頭で女性が「关于中国各民族服装的讲座（中国各民族の衣装に関する講座）」と言っているため、D「民族服装」がそのまま正解になります。","tipJa":"冒頭の「关于〜的讲座」に加え、後半の「试穿（試着する）」からも衣装がテーマだと確実に裏付けられます。"},{"id":10,"section":"listening","partId":"L1","kind":"mcq","options":[{"label":"A","text":"怕小狗无聊","meaningJa":"子犬が退屈するのを心配して"},{"label":"B","text":"认为小狗可靠","meaningJa":"子犬が頼りになると思って"},{"label":"C","text":"把小狗当家人","meaningJa":"子犬を家族同然と思っているから"},{"label":"D","text":"想让婚礼有趣","meaningJa":"結婚式を面白くしたいから"}],"answer":"C","audio":{"start":418.35,"end":444.95},"transcript":[{"speaker":"男","text":"婚礼上送戒指的环节，你打算怎么安排？","ja":"結婚式で指輪を運ぶ演出、どう手配するつもり？"},{"speaker":"女","text":"我想让毛毛送，就是怕它调皮到处乱跑。","ja":"毛毛（愛犬）に運ばせたいんだけど、いたずらで走り回らないか心配なの。"},{"speaker":"男","text":"小狗做花童真有创意，毛毛很聪明，没问题的。","ja":"ワンちゃんがリングボーイをやるなんて斬新だね。毛毛は賢いから大丈夫だよ。"},{"speaker":"女","text":"嗯，毛毛也是我的家人，我人生中的重要时刻，也想让它出席。","ja":"ええ、毛毛も私の家族だから、人生の大切な瞬間にやっぱり出席してほしいの。"},{"speaker":"问","text":"女的为什么想让小狗出席婚礼？","ja":"女性はどうして愛犬を結婚式に出席させたいのですか？"}],"translationJa":"男：結婚式の指輪運びの演出はどうする？\\n女：毛毛に運ばせたいけど、いたずらして走り回らないか心配で。\\n男：犬が花童なんてアイデア抜群だね、毛毛は賢いから大丈夫。\\n女：うん、毛毛も私の家族だから人生の大事な瞬間にいてほしいの。\\n【質問】女性はなぜ愛犬を結婚式に出席させたいのですか？","explanationJa":"女性の最後の発言「毛毛也是我的家人，我人生中的重要时刻，也想让它出席（毛毛も私の家族だから大切な瞬間に参加してほしい）」が理由そのものであり、C「把小狗当家人」が正解です。","tipJa":"「真有创意（アイデアが面白い）」は男性の感想であり、女性本人の理由（D）ではない点に注意しましょう。「花童（フラワーガール／リングボーイ）」も覚えておくと便利です。"},{"id":11,"section":"listening","partId":"L1","kind":"mcq","groupId":"hsk5-l1-11-12","options":[{"label":"A","text":"利于表达情感","meaningJa":"感情表現に役立つ"},{"label":"B","text":"能让人发挥想象","meaningJa":"見る人の想像力を広げられる"},{"label":"C","text":"是一种写作方法","meaningJa":"文章作成の手法の一種である"},{"label":"D","text":"意味着大范围删改","meaningJa":"大幅な削除・修正を意味する"}],"answer":"B","audio":{"start":460.15,"end":509.55},"transcript":[{"speaker":"问","text":"关于留白，可以知道什么？","ja":"「留白（余白）」について何がわかりますか？"}],"translationJa":"【質問】「留白（余白）」について何がわかりますか？","explanationJa":"男性の「要留下更多想象的空间（想像の余地をより多く残すということですね？）」に対して、女性が「没错，带给人想象的同时……（その通り、人に想像をもたらすと同時に……）」と肯定しているため、B「能让人发挥想象」が正解です。","tipJa":"「源于国画创作（中国画に由来）」なので C（写作方法＝文章執筆法）は誤り。専門用語が出ても対話内の言い換え（「想象的空间」）を聞き取れば確実に解けます。"},{"id":12,"section":"listening","partId":"L1","kind":"mcq","groupId":"hsk5-l1-11-12","options":[{"label":"A","text":"色彩对比弱","meaningJa":"色彩のコントラストが弱い"},{"label":"B","text":"主题不够突出","meaningJa":"テーマが十分に際立っていない"},{"label":"C","text":"背景比较模糊","meaningJa":"背景がややぼやけている"},{"label":"D","text":"天空所占比例大","meaningJa":"空が占める割合が大きい"}],"answer":"B","audio":{"start":460.15,"end":529.35},"transcript":[{"speaker":"问","text":"女的觉得那张落日的照片怎么样？","ja":"女性はその夕日の写真についてどう感じていますか？"}],"translationJa":"【質問】女性はその夕日の写真をどう評価していますか？","explanationJa":"女性が「要是你能把更多的画面留给天空和大海，那么照片会更有意境，主题也更突出（もっと空と海に画面を割けば、より趣が出てテーマも際立つのに）」と仮定法で助言しているため、現状はテーマが十分際立っていない（B）ことがわかります。","tipJa":"「要是……那么就更……（もし〜ならもっと〜になるのに）」という仮定の助言表現は、現在の欠点を暗示する頻出パターン！空の割合を増やすべきと言っているので D は逆のひっかけです。"},{"id":13,"section":"listening","partId":"L1","kind":"mcq","groupId":"hsk5-l1-13-14","options":[{"label":"A","text":"及时调整好心态","meaningJa":"すぐに気持ちを切り替える"},{"label":"B","text":"请裁判暂停比赛","meaningJa":"審判に試合中断を求める"},{"label":"C","text":"向教练请求帮助","meaningJa":"コーチに助けを求める"},{"label":"D","text":"总结失败的经验","meaningJa":"失敗の経験を総括する"}],"answer":"A","audio":{"start":544.4,"end":596.3},"transcript":[{"speaker":"问","text":"女的认为应该怎么对待比赛中的失误？","ja":"女性は試合中のミスにどう向き合うべきだと考えていますか？"}],"translationJa":"【質問】女性は試合中のミスにどう対処すべきだと考えていますか？","explanationJa":"女性が「即使这一球失误了，也不要轻易放弃，要立刻调整好心态（たとえ1球ミスしても諦めず、すぐメンタルを立て直すべきだ）」と語っているため、A「及时调整好心态」が正解です。","tipJa":"「立刻（即座に）」→「及时（タイムリーに・すぐさま）」の言い換えに気づけると即答できます。「心态（メンタル・心構え）」はスポーツ・心理学系の重要語彙です。"},{"id":14,"section":"listening","partId":"L1","kind":"mcq","groupId":"hsk5-l1-13-14","options":[{"label":"A","text":"成绩下降得很快","meaningJa":"成績が急激に下がった"},{"label":"B","text":"把李娜当作对手","meaningJa":"李娜をライバル視している"},{"label":"C","text":"目标是保持进步","meaningJa":"目標は進歩し続けることだ"},{"label":"D","text":"根本不在乎结果","meaningJa":"結果をまったく気にしていない"}],"answer":"C","audio":{"start":544.4,"end":615.15},"transcript":[{"speaker":"问","text":"关于女的，可以知道什么？","ja":"女性について何がわかりますか？"}],"translationJa":"【質問】女性について何がわかりますか？","explanationJa":"最後に「现在我想做的就是挑战自我，能不断进步就好（今は自分に挑戦し、絶えず進歩できればいい）」と述べているため、C「目标是保持进步」が正解です。","tipJa":"ひっかけに注意！Bはかつての「目標（目标）」であって「対戦相手（对手）」ではなく、Dは「不要过多考虑结果（考えすぎない）」であって「根本不在乎（まったく気にしない）」という極端な表現は誤りです。"},{"id":15,"section":"listening","partId":"L1","kind":"mcq","groupId":"hsk5-l1-15-16","options":[{"label":"A","text":"牙齿","meaningJa":"歯"},{"label":"B","text":"胳膊","meaningJa":"腕"},{"label":"C","text":"手指","meaningJa":"指"},{"label":"D","text":"眼睛","meaningJa":"目"}],"answer":"D","audio":{"start":629.9,"end":675},"transcript":[{"speaker":"问","text":"男的把传感器系统比喻为什么？","ja":"男性はセンサーシステムを何に例えましたか？"}],"translationJa":"【質問】男性はセンサーシステムを何に例えましたか？","explanationJa":"男性が「安装了先进的传感器系统，就像它的眼睛，能灵活避开家具（先進的なセンサーシステムを搭載しており、まるで目のようだ）」と述べているため、D「眼睛」が正解です。","tipJa":"「把A比喻为B（AをBに例える）」は設問文の定番表現。音声中の「就像〜（まるで〜のようだ）」が比喩の合図です。"},{"id":16,"section":"listening","partId":"L1","kind":"mcq","groupId":"hsk5-l1-15-16","options":[{"label":"A","text":"需每日充电","meaningJa":"毎日充電する必要がある"},{"label":"B","text":"能语音控制","meaningJa":"音声操作ができる"},{"label":"C","text":"现在正在促销","meaningJa":"現在セール中である"},{"label":"D","text":"两年内免费换新","meaningJa":"2年以内なら無料で新品交換できる"}],"answer":"C","audio":{"start":629.9,"end":695.05},"transcript":[{"speaker":"问","text":"关于扫地机器人，下列哪项正确？","ja":"お掃除ロボットについて正しいのはどれですか？"}],"translationJa":"【質問】お掃除ロボットについて正しいのは次のうちどれですか？","explanationJa":"男性は「正好商场在做促销活动，我就买了（ちょうどモールでセールをしていたので買った）」と述べており、C「现在正在促销」が正解です。","tipJa":"Dは巧妙な数字すり替えの罠！音声では「两年售后保障服务（2年アフター保証）」「一年内免费更换新机（1年以内無料新品交換）」なので、2年と1年を混同しないよう要注意です。"},{"id":17,"section":"listening","partId":"L1","kind":"mcq","groupId":"hsk5-l1-17-19","options":[{"label":"A","text":"了解不深","meaningJa":"理解が深くない"},{"label":"B","text":"过于乐观","meaningJa":"楽観的すぎる"},{"label":"C","text":"缺乏耐心","meaningJa":"忍耐力が足りない"},{"label":"D","text":"不够敏感","meaningJa":"敏感さが足りない"}],"answer":"A","audio":{"start":709.95,"end":783.6},"transcript":[{"speaker":"问","text":"当前，家长面对孩子的心理疾病时普遍存在什么问题？","ja":"現在、保護者が子どもの心の病に直面したとき、一般的にどのような問題がありますか？"}],"translationJa":"【質問】現在、保護者が子どもの心の病に向き合う際、一般的にどんな問題がありますか？","explanationJa":"男性は「从整体上来说，了解得还是不够（全体として見れば理解はまだ不十分だ）」と端的に述べており、A「了解不深」と一致します。","tipJa":"「虽然〜，但从整体上来说〜」という譲歩＋逆接の後ろが話し手の本論です。「不够（不十分だ）」→「不深（深くない）」の言い換えに注目しましょう。"},{"id":18,"section":"listening","partId":"L1","kind":"mcq","groupId":"hsk5-l1-17-19","options":[{"label":"A","text":"让孩子主动提问","meaningJa":"子どもに自ら質問させる"},{"label":"B","text":"单独与孩子交流","meaningJa":"子どもと1対1で話す"},{"label":"C","text":"先向同学了解情况","meaningJa":"まず同級生から状況を聞く"},{"label":"D","text":"鼓励父母优先参与","meaningJa":"両親が優先的に参加するよう促す"}],"answer":"D","audio":{"start":709.95,"end":804.25},"transcript":[{"speaker":"问","text":"遇到青少年心理咨询时，男的通常怎么做？","ja":"青少年の心理カウンセリングの際、男性は普段どのようにしますか？"}],"translationJa":"【質問】青少年の心理相談を受けた際、男性は普段どう対応しますか？","explanationJa":"男性は「只有孩子去接受咨询是不够的，家长必须先参与进来。父母得先从自己做起（子どもだけの相談では不十分で、まず親が参加し自分から変わるべきだ）」と述べているため、D「鼓励父母优先参与」が正解です。","tipJa":"「先参与进来（まず参加する）」「先从自己做起（まず自分から始める）」が D の「优先参与」に対応しています。長い対話では質問ごとに話題が切り替わるので、インタビュアーの2番目の質問を起点に追うと整理しやすいです。"},{"id":19,"section":"listening","partId":"L1","kind":"mcq","groupId":"hsk5-l1-17-19","options":[{"label":"A","text":"时常表扬孩子","meaningJa":"頻繁に子どもを褒める"},{"label":"B","text":"耐心听孩子说话","meaningJa":"辛抱強く子どもの話を聞く"},{"label":"C","text":"多帮孩子做决定","meaningJa":"子どもの代わりに多く決断してあげる"},{"label":"D","text":"无条件信任孩子","meaningJa":"無条件に子どもを信頼する"}],"answer":"B","audio":{"start":709.95,"end":825.6},"transcript":[{"speaker":"问","text":"男的认为家长如何才能与孩子建立良好关系？","ja":"男性は親がどうすれば子どもと良好な関係を築けると考えていますか？"}],"translationJa":"【質問】男性は、親がどうすれば子どもと良い関係を築けると考えていますか？","explanationJa":"男性は「要尊重孩子，听他们说话时别急着下结论，要试着理解他们的感受（子どもを尊重し、話を聞くとき急いで結論を出さず気持ちを理解しようと努めるべきだ）」と答えており、これを端的に表す B「耐心听孩子说话」が正解です。","tipJa":"「别急着下结论（急いで結論づけるな）」が「耐心（辛抱強く）」に言い換えられています。対話の最終ターンが最終設問（Q19）にそのまま対応する典型構造です。"},{"id":20,"section":"listening","partId":"L2","kind":"mcq","groupId":"hsk5-l2-20-21","options":[{"label":"A","text":"路人","meaningJa":"通行人"},{"label":"B","text":"记者","meaningJa":"記者"},{"label":"C","text":"列车长","meaningJa":"車掌長"},{"label":"D","text":"售票员","meaningJa":"切符販売員"}],"answer":"C","audio":{"start":856.8,"end":904.85},"transcript":[{"speaker":"问","text":"说话人是什么身份？","ja":"話し手はどのような立場の人ですか？"}],"translationJa":"【質問】話し手はどのような身分の人ですか？","explanationJa":"アナウンスの冒頭で「我是本次列车的列车长（私は本列車の車掌長です）」と名乗っているため、C「列车长」が正解です。","tipJa":"L2の第1問は冒頭の数秒に答えが隠れていることが非常に多いので、選択肢を先読みして「人物・身分」を問われそうだと予測しておくと余裕を持って聞き取れます。"},{"id":21,"section":"listening","partId":"L2","kind":"mcq","groupId":"hsk5-l2-20-21","options":[{"label":"A","text":"暴雨影响","meaningJa":"豪雨の影響"},{"label":"B","text":"前方地震","meaningJa":"前方での地震"},{"label":"C","text":"系统出现错误","meaningJa":"システムにエラーが発生した"},{"label":"D","text":"给其他车让行","meaningJa":"他の列車に道を譲った"}],"answer":"A","audio":{"start":856.8,"end":924.4},"transcript":[{"speaker":"问","text":"列车为什么会晚点？","ja":"列車はなぜ遅延したのですか？"}],"translationJa":"【質問】列車はなぜ遅れたのですか？","explanationJa":"「受暴雨天气影响，列车晚点半个小时（豪雨の影響を受け、列車は30分遅延しました）」と明言しているため、A「暴雨影响」が正解です。","tipJa":"「受〜影响（〜の影響を受ける）」「晚点（交通機関が遅延する）」は交通アナウンスの超頻出セット表現です。"},{"id":22,"section":"listening","partId":"L2","kind":"mcq","groupId":"hsk5-l2-22-23","options":[{"label":"A","text":"收集种子","meaningJa":"種を集めること"},{"label":"B","text":"回收垃圾","meaningJa":"ゴミを回収すること"},{"label":"C","text":"感受大自然","meaningJa":"大自然を感じること"},{"label":"D","text":"掌握生存技能","meaningJa":"サバイバル技術を身につけること"}],"answer":"C","audio":{"start":940.15,"end":1005.65},"transcript":[{"speaker":"问","text":"现在人们去捡秋的目的是什么？","ja":"現在人々が「捡秋（秋拾い）」へ行く目的は何ですか？"}],"translationJa":"【質問】現在人々が「捡秋」をする目的は何ですか？","explanationJa":"「现在的“捡秋”更多是指在秋天时，人们走到户外，捡落叶、果实等以感受大自然，享受秋天的美好」と述べられているため、C「感受大自然」が正解です。","tipJa":"「以前（昔）」と「现在（現在）」の対比構造に注目！設問は「现在」の目的を聞いているので、後半の定義をしっかり拾いましょう。"},{"id":23,"section":"listening","partId":"L2","kind":"mcq","groupId":"hsk5-l2-22-23","options":[{"label":"A","text":"衣服要轻薄","meaningJa":"服装は薄手にする"},{"label":"B","text":"多采集果实","meaningJa":"木の実をたくさん採取する"},{"label":"C","text":"爱护当地环境","meaningJa":"現地の環境を大切にする"},{"label":"D","text":"尽量独立行动","meaningJa":"なるべく単独行動する"}],"answer":"C","audio":{"start":940.15,"end":1025.55},"transcript":[{"speaker":"问","text":"捡秋时应该注意什么？","ja":"「捡秋」のときに何に注意すべきですか？"}],"translationJa":"【質問】「捡秋」の際に注意すべきことは何ですか？","explanationJa":"「需要注意的是，参与“捡秋”活动时要保护环境，尽量减少对自然资源的破坏」と述べられているため、C「爱护当地环境」が正解です。","tipJa":"B「多采集果实」は本文の「不要过度采集」と正反対、D「尽量独立行动」は「最好和伙伴一起行动」と正反対の典型的なひっかけ選択肢です。"},{"id":24,"section":"listening","partId":"L2","kind":"mcq","groupId":"hsk5-l2-24-26","options":[{"label":"A","text":"弹琴","meaningJa":"琴を弾くこと"},{"label":"B","text":"游玩","meaningJa":"遊び歩くこと・遊山"},{"label":"C","text":"写诗","meaningJa":"詩を書くこと"},{"label":"D","text":"练书法","meaningJa":"書道を練習すること"}],"answer":"B","audio":{"start":1041.3,"end":1115.25},"transcript":[{"speaker":"问","text":"苏洵年少时有什么爱好？","ja":"蘇洵は若いころどんな趣味がありましたか？"}],"translationJa":"【質問】蘇洵は若いころどのような趣味を持っていましたか？","explanationJa":"冒頭で「苏洵少时不爱读书，只喜欢游山玩水（蘇洵は若いころ勉強を好まず、山川を巡って遊ぶことだけが好きだった）」と語られているため、B「游玩」が正解です。","tipJa":"「游山玩水（自然の風景を楽しみながら遊び歩く）」という四字熟語を「游玩」と言い換えています。歴史人物の逸話では冒頭に人物の若いころの特徴が出ます。"},{"id":25,"section":"listening","partId":"L2","kind":"mcq","groupId":"hsk5-l2-24-26","options":[{"label":"A","text":"把书藏起来","meaningJa":"本を隠すこと"},{"label":"B","text":"制定阅读规则","meaningJa":"読書ルールを決めること"},{"label":"C","text":"固定学习时间","meaningJa":"勉強時間を固定すること"},{"label":"D","text":"让儿子大声读书","meaningJa":"息子に音読させること"}],"answer":"A","audio":{"start":1041.3,"end":1135.25},"transcript":[{"speaker":"问","text":"苏洵的哪种做法起了作用？","ja":"蘇洵のどのやり方が効果を発揮しましたか？"}],"translationJa":"【質問】蘇洵のどのようなやり方が効を奏しましたか？","explanationJa":"「只要两个孩子一靠近，他便赶紧把书藏起来。这激发了兄弟俩的好奇心（子どもが近づくと慌てて本を隠した。これが兄弟の好奇心を刺激した）」とあるため、A「把书藏起来」が正解です。","tipJa":"「起作用（効果を発揮する・効き目がある）」は非常によく出る連語表現です。故事・逸話問題では「工夫した方法→その結果」の因果を押さえましょう。"},{"id":26,"section":"listening","partId":"L2","kind":"mcq","groupId":"hsk5-l2-24-26","options":[{"label":"A","text":"总是躲起来","meaningJa":"いつも隠れるようになった"},{"label":"B","text":"很信任父亲","meaningJa":"父親を深く信頼した"},{"label":"C","text":"发起了改革","meaningJa":"改革を起こした"},{"label":"D","text":"成了文学家","meaningJa":"文学者になった"}],"answer":"D","audio":{"start":1041.3,"end":1155.4},"transcript":[{"speaker":"问","text":"苏洵的儿子后来怎么样了？","ja":"蘇洵の息子たちは後にどうなりましたか？"}],"translationJa":"【質問】蘇洵の息子たちはその後どうなりましたか？","explanationJa":"結末に「为日后成为著名文学家打下了基础（後に著名な文学者となる基盤を築いた）」とあるため、D「成了文学家」が正解です。","tipJa":"蘇洵・蘇軾（蘇東坡）・蘇轍は「三蘇」として唐宋八大家に数えられる超有名親子！中国文化の背景知識があると聴解が一気に楽になります。"},{"id":27,"section":"listening","partId":"L2","kind":"mcq","groupId":"hsk5-l2-27-29","options":[{"label":"A","text":"车超速了","meaningJa":"車がスピード違反していた"},{"label":"B","text":"是货车司机","meaningJa":"トラック運転手である"},{"label":"C","text":"卖的蔬菜很新鲜","meaningJa":"売っている野菜がとても新鮮だ"},{"label":"D","text":"被送往了医院治疗","meaningJa":"病院へ搬送され治療を受けた"}],"answer":"D","audio":{"start":1171.15,"end":1253.25},"transcript":[{"speaker":"问","text":"关于曹先生，可以知道什么？","ja":"曹さんについて何がわかりますか？"}],"translationJa":"【質問】曹さんについて何がわかりますか？","explanationJa":"「随后120及时赶到，将他送往医院治疗（その後救急車がすぐ到着し、彼を病院へ搬送して治療した）」とそのまま述べられているため、D「被送往了医院治疗」が正解です。","tipJa":"中国では「120」が救急車（日本の119に相当）を指します。本文で曹さんは「菜农（野菜農家）」と紹介されており、B（货车司机）は本文にない推測なので×です。"},{"id":28,"section":"listening","partId":"L2","kind":"mcq","groupId":"hsk5-l2-27-29","options":[{"label":"A","text":"赠送给路人","meaningJa":"通行人に無料で配った"},{"label":"B","text":"运输到垃圾站","meaningJa":"ゴミ処理場へ運んだ"},{"label":"C","text":"按市场价购买","meaningJa":"市場価格で買い取った"},{"label":"D","text":"送到附近菜市场","meaningJa":"近くの市場へ届けた"}],"answer":"C","audio":{"start":1171.15,"end":1274.1},"transcript":[{"speaker":"问","text":"交警们是如何处理曹先生的蔬菜的？","ja":"交通警察たちは曹さんの野菜をどのように処理しましたか？"}],"translationJa":"【質問】交通警察たちは曹さんの野菜をどのように扱いましたか？","explanationJa":"「中队的民辅警们纷纷主动提供帮助，按照市场价格，一人一袋，将剩余蔬菜全部买走（市場価格で1人1袋ずつ残りの野菜をすべて買い取った）」とあるため、C「按市场价购买」が正解です。","tipJa":"「民辅警」は「民警（正規警察官）＋辅警（補助警察官）」の略称で、中国の社会ニュースで頻出する語彙です。"},{"id":29,"section":"listening","partId":"L2","kind":"mcq","groupId":"hsk5-l2-27-29","options":[{"label":"A","text":"补交罚款","meaningJa":"罰金を追加納付するため"},{"label":"B","text":"领取车辆","meaningJa":"車両を引き取るため"},{"label":"C","text":"配合事故调查","meaningJa":"事故調査に協力するため"},{"label":"D","text":"向民辅警表示感谢","meaningJa":"警察官・補助警官に感謝を伝えるため"}],"answer":"D","audio":{"start":1171.15,"end":1295.25},"transcript":[{"speaker":"问","text":"曹先生的妻子为什么特意赶到中队？","ja":"曹さんの妻はなぜわざわざ中隊へ駆けつけたのですか？"}],"translationJa":"【質問】曹さんの妻はなぜわざわざ中隊を訪れたのですか？","explanationJa":"「第二天，曹先生的妻子特意赶到中队，向民辅警们表达感激之情（翌日、曹さんの妻はわざわざ中隊を訪れ、感謝の気持ちを伝えた）」とあるため、D「向民辅警表示感谢」が正解です。","tipJa":"「特意（わざわざ）」「表达感激之情（感謝の意を表する）」がそのまま答えの決め手になっています。温かい人情ニュースはHSK5級の定番ジャンルです。"},{"id":30,"section":"listening","partId":"L2","kind":"mcq","groupId":"hsk5-l2-30-32","options":[{"label":"A","text":"缓解疼痛","meaningJa":"痛みを和らげる"},{"label":"B","text":"放松心情","meaningJa":"気持ちをリラックスさせる"},{"label":"C","text":"集中精力","meaningJa":"精力を集中させる"},{"label":"D","text":"追求刺激","meaningJa":"刺激を追い求める"}],"answer":"B","audio":{"start":1311.15,"end":1378.6},"transcript":[{"speaker":"问","text":"抽烟的人一般有什么需求？","ja":"喫煙する人には一般的にどのような欲求がありますか？"}],"translationJa":"【質問】タバコを吸う人は一般的にどんな欲求を持っていますか？","explanationJa":"「有的人喜欢抽烟，因为抽烟让他感到放松，可以暂时远离生活和工作的压力（タバコがリラックスさせ、一時的にストレスから離れられるため）」と説明されているため、B「放松心情」が正解です。","tipJa":"具体例の導入表現「举个例子（例えば）」の直後に Q30 の根拠が登場します。論説文では「抽象論→具体例」の切り替えに耳を澄ませましょう。"},{"id":31,"section":"listening","partId":"L2","kind":"mcq","groupId":"hsk5-l2-30-32","options":[{"label":"A","text":"摄影","meaningJa":"写真撮影"},{"label":"B","text":"运动","meaningJa":"運動"},{"label":"C","text":"吸电子烟","meaningJa":"電子タバコを吸う"},{"label":"D","text":"吃无糖饼干","meaningJa":"無糖ビスケットを食べる"}],"answer":"D","audio":{"start":1311.15,"end":1401.1},"transcript":[{"speaker":"问","text":"根据这段话，下列哪种方式有助于远离垃圾食品？","ja":"この話によると、次のどの方法がジャンクフードから離れるのに役立ちますか？"}],"translationJa":"【質問】この話によると、ジャンクフードをやめるのに役立つ方法はどれですか？","explanationJa":"最後の文で「如果想戒掉垃圾食品，可以手边放一些健康的小零食，比如不含糖的饼干、酸奶等（ジャンクフードをやめたければ無糖ビスケットやヨーグルトなど健康的な軽食を置くとよい）」とあるため、D「吃无糖饼干」が正解です。","tipJa":"B「运动」は本文に出てきますが、それは「戒烟（禁煙）」の代替案であって「垃圾食品（ジャンクフード）」の対策ではない点に注意！対象と例を正しく紐づけましょう。"},{"id":32,"section":"listening","partId":"L2","kind":"mcq","groupId":"hsk5-l2-30-32","options":[{"label":"A","text":"要下定决心","meaningJa":"固い決意をすること"},{"label":"B","text":"有判断能力","meaningJa":"判断力を持つこと"},{"label":"C","text":"用好习惯代替","meaningJa":"良い習慣で置き換えること"},{"label":"D","text":"与优秀的人相处","meaningJa":"優秀な人と付き合うこと"}],"answer":"C","audio":{"start":1311.15,"end":1422.85},"transcript":[{"speaker":"问","text":"根据这段话，改掉一个坏习惯的关键是什么？","ja":"この話によると、悪い習慣を改める鍵は何ですか？"}],"translationJa":"【質問】この話によると、悪い習慣を直す鍵は何ですか？","explanationJa":"文章の核心命題である「替换理论认为，习惯不可能被磨灭，只能被取代（置換理論では、習慣は消し去ることはできず、置き換えることしかできない）」およびガム・運動・無糖ビスケットの例から、C「用好习惯代替」が正解です。","tipJa":"「替换／取代／替代」という類義語が何度も繰り返されており、まさにそれが全体のキーワード！繰り返し聞こえる中心概念がそのまま要旨問題の正解になります。"},{"id":33,"section":"listening","partId":"L2","kind":"mcq","groupId":"hsk5-l2-33-35","options":[{"label":"A","text":"情绪变化","meaningJa":"感情の変化"},{"label":"B","text":"身体数据","meaningJa":"身体データ"},{"label":"C","text":"运动安排","meaningJa":"運動スケジュール"},{"label":"D","text":"饮食搭配","meaningJa":"食事の組み合わせ"}],"answer":"A","audio":{"start":1438.8,"end":1509.95},"transcript":[{"speaker":"问","text":"下列哪项不属于王春程记录的内容？","ja":"次のうち王春程が記録した内容に含まれないものはどれですか？"}],"translationJa":"【質問】次のうち、王春程さんが記録した内容に該当しないものはどれですか？","explanationJa":"音声では「包括身体数据、运动安排、饮食搭配（身体データ、運動計画、食事の組み合わせを含む）」とB・C・Dの3つが列挙されており、言及のない A「情绪变化」が「不属于（属さない）」の正解です。","tipJa":"「不属于〜（〜に属さない）」という否定設問！選択肢が4つとも同じジャンル（記録項目）で並んでいるときは、聞きながら聞こえた項目に心の中でチェックを付けると瞬時に解けます。"},{"id":34,"section":"listening","partId":"L2","kind":"mcq","groupId":"hsk5-l2-33-35","options":[{"label":"A","text":"培养学术思维","meaningJa":"学術的思考を養う"},{"label":"B","text":"使研究娱乐化","meaningJa":"研究を娯楽化する"},{"label":"C","text":"能发现生活的美好","meaningJa":"生活の美しさを発見できる"},{"label":"D","text":"提高解决问题的效率","meaningJa":"問題解決の効率を高める"}],"answer":"A","audio":{"start":1438.8,"end":1532.3},"transcript":[{"speaker":"问","text":"王春程认为，以学术的眼光观察生活有什么意义？","ja":"王春程は、学術的な視点で生活を観察することにどんな意義があると考えていますか？"}],"translationJa":"【質問】王春程さんは、学術的視点で日常を観察することにどんな意義があると考えていますか？","explanationJa":"本人の発言「以学术眼光去观察日常生活，能够帮助我形成学术思维，激发更多的创造力（学術的思考の形成を助け、創造力を引き出す）」より、A「培养学术思维」が正解です。","tipJa":"「形成学术思维（学術的思考を形成する）」→「培养学术思维（学術的思考を養う）」の言い換え。「某某说：『……』」の引用文は必ず設問のターゲットになります。"},{"id":35,"section":"listening","partId":"L2","kind":"mcq","groupId":"hsk5-l2-33-35","options":[{"label":"A","text":"无奈","meaningJa":"どうしようもない・やれやれ"},{"label":"B","text":"称赞","meaningJa":"称賛"},{"label":"C","text":"怀疑","meaningJa":"疑い"},{"label":"D","text":"不在乎","meaningJa":"無関心・気にしない"}],"answer":"B","audio":{"start":1438.8,"end":1553.85},"transcript":[{"speaker":"问","text":"同学们对王春程这篇论文持什么态度？","ja":"学生たちは王春程のこの論文に対してどのような態度をとっていますか？"}],"translationJa":"【質問】学生たちは王春程さんのこの論文にどのような態度を示しましたか？","explanationJa":"最後に「大家纷纷点赞留言：『能对自己有这么精确的记录和了解，真是太厉害了！』」とあり、いいねや「本当にすごい！」というコメントが殺到しているため、B「称赞（称賛）」が正解です。","tipJa":"態度問題（「持什么态度」）はHSK5・6級の定番です。選択肢に感情・態度語（无奈・称赞・怀疑など）が並んだら、話の結びの評価や反応に集中しましょう。"},{"id":36,"section":"reading","partId":"R1","kind":"mcq","groupId":"hsk5-r1-36-38","promptZh":"外公听了高兴地称赞道：“外孙女真【36】，外公必须得奖励你。”","options":[{"label":"A","text":"不要紧","meaningJa":"構わない・大したことない"},{"label":"B","text":"了不起","meaningJa":"すごい・立派だ"},{"label":"C","text":"受不了","meaningJa":"耐えられない"},{"label":"D","text":"开玩笑","meaningJa":"冗談を言う"}],"answer":"B","translationJa":"おじいちゃんは聞いて嬉しそうに褒めました。「孫娘は本当にすごいね、おじいちゃんはご褒美をあげなきゃな」","explanationJa":"前の「称赞道（褒めて言った）」や後ろの「奖励你（ご褒美をあげる）」と響き合う褒め言葉が必要なので、B「了不起（すごい・立派だ）」が最適です。","tipJa":"「称赞（褒める）」はプラス評価の語を選ぶ最強のヒント！「真了不起（本当にすごい）」は口語・書き言葉ともに定番の褒め表現です。"},{"id":37,"section":"reading","partId":"R1","kind":"mcq","groupId":"hsk5-r1-36-38","promptZh":"文文把红包【37】给了妈妈，说：“请把我的工资收好。”","options":[{"label":"A","text":"递","meaningJa":"手渡す"},{"label":"B","text":"拆","meaningJa":"開ける・分解する"},{"label":"C","text":"赔","meaningJa":"弁償する"},{"label":"D","text":"派","meaningJa":"派遣する"}],"answer":"A","translationJa":"文文はお年玉袋（紅包）をママに手渡し、「私のお給料をしまっておいて」と言いました。","explanationJa":"「把A递给B（AをBに手渡す）」が自然なコロケーションです。「拆」は封を開ける意で「拆给」とは言わず、C（弁償）・D（派遣）も文脈に合いません。","tipJa":"「递给〜（〜に手渡す）」は一文字動詞の頻出問題！動作の受け手「给＋人」と結びつく動詞を見極めましょう。"},{"id":38,"section":"reading","partId":"R1","kind":"mcq","groupId":"hsk5-r1-36-38","promptZh":"妈妈笑问：“你才四岁，又不上班，【38】？”","options":[{"label":"A","text":"一旦下了班","meaningJa":"いったん退勤したら"},{"label":"B","text":"哪儿有奖金","meaningJa":"ボーナスなんてどこにあるの"},{"label":"C","text":"居然都有工资了","meaningJa":"なんと給料までもらうようになったの"},{"label":"D","text":"每个月的收入都要给我","meaningJa":"毎月の収入を全部私にくれるの"}],"answer":"C","translationJa":"ママは笑いながら尋ねました。「まだ4歳で仕事もしてないのに、なんと給料までもらうようになったの？」","explanationJa":"直前に文文が「我的工资（私のお給料）」と言ったのを受けて、驚きとユーモアを込めて聞き返す C「居然都有工资了」が文脈にぴったり合います。","tipJa":"小話のオチは「上班（出勤する）」と「上小班（幼稚園の年少組に通う）」のダジャレ！文中のキーワード「工资」をそのまま引き継ぐ選択肢 C を選ぶのが鉄則です。"},{"id":39,"section":"reading","partId":"R1","kind":"mcq","groupId":"hsk5-r1-39-41","promptZh":"全书7000多字，篇幅并不长，【39】。","options":[{"label":"A","text":"却有很多错字","meaningJa":"しかし誤字がたくさんある"},{"label":"B","text":"让人不能理解","meaningJa":"人に理解できない"},{"label":"C","text":"但内容相当丰富","meaningJa":"しかし内容は非常に豊富である"},{"label":"D","text":"读起来有很大负担","meaningJa":"読むのに大きな負担がかかる"}],"answer":"C","translationJa":"全書7,000字あまりで分量自体は長くないが、内容は非常に豊富である。","explanationJa":"直後に「6大分類30職種の内容を記載」「数学・力学・声学など多方面の知識を総括」と内容の豊富さが詳述されているため、逆接でつなぐ C「但内容相当丰富」が正解です。","tipJa":"空欄の「後ろの文」が具体説明になっている典型パターン！マイナス評価の A・B・D は文全体の賞賛トーンと合いません。"},{"id":40,"section":"reading","partId":"R1","kind":"mcq","groupId":"hsk5-r1-39-41","promptZh":"该书记载了木工、金工、皮革、染色、刮磨、陶瓷等六大类三十个工种的内容，【40】了当时中国所达到的科技及工艺水平。","options":[{"label":"A","text":"创造","meaningJa":"創造する"},{"label":"B","text":"反映","meaningJa":"反映する"},{"label":"C","text":"建设","meaningJa":"建設する"},{"label":"D","text":"表达","meaningJa":"表現する・伝える"}],"answer":"B","translationJa":"本書には6大分類30職種の内容が記載されており、当時の中国が到達した科学技術および工芸水準を反映している。","explanationJa":"書物の記述が客観的な当時の「水平（水準）」を映し出す場合は「反映（反映する）」を使います。D「表达」は感情・意見・考えに用いるため「水平」とは結びつきません。","tipJa":"「反映＋水平／情况／问题（水準・状況・問題を反映する）」は書き言葉の鉄板コロケーションです。「表达（感情・意見）」との使い分けはHSK5・6級の超頻出ポイント！"},{"id":41,"section":"reading","partId":"R1","kind":"mcq","groupId":"hsk5-r1-39-41","promptZh":"《考工记》在中国科技史、工艺美术史和文化史上都占有重要【41】。","options":[{"label":"A","text":"成就","meaningJa":"成果・業績"},{"label":"B","text":"样式","meaningJa":"様式・スタイル"},{"label":"C","text":"业务","meaningJa":"業務"},{"label":"D","text":"地位","meaningJa":"地位"}],"answer":"D","translationJa":"『考工記』は中国の科学技術史・工芸美術史・文化史において重要な地位を占めている。","explanationJa":"「占有重要地位（重要な地位を占める）」は不動の固定表現です。A「成就」は「取得成就（成果を上げる）」と組み合わせるため「占有」とは合いません。","tipJa":"「占有重要地位（重要な地位を占める）」はそのまま1フレーズで暗記！動詞「占有」を見たら即座に「地位」を連想できるようにしましょう。"},{"id":42,"section":"reading","partId":"R1","kind":"mcq","groupId":"hsk5-r1-42-45","promptZh":"首先是方便。【42】，电动自行车在启动和停车时花费的时间最少。","options":[{"label":"A","text":"也有人反对","meaningJa":"反対する人もいる"},{"label":"B","text":"不用担心堵车","meaningJa":"渋滞を心配する必要がない"},{"label":"C","text":"比起其他交通工具","meaningJa":"他の交通手段と比べて"},{"label":"D","text":"电动自行车快速发展","meaningJa":"電動自転車は急速に発展している"}],"answer":"C","translationJa":"第一に便利さだ。他の交通手段と比べて、電動自転車は発進と駐車に要する時間が最も短い。","explanationJa":"後ろに「花费的时间最少（かかる時間が最も少ない）」という最上級表現があるため、比較対象を提示する C「比起其他交通工具」が論理的に完璧につながります。","tipJa":"後ろの「最〜（最も〜）」という表現は、前の「比起〜（〜と比べて）」と呼応する強力な手がかりになります。"},{"id":43,"section":"reading","partId":"R1","kind":"mcq","groupId":"hsk5-r1-42-45","promptZh":"再加上占地【43】小，车主也不再为找车位而发愁。","options":[{"label":"A","text":"场所","meaningJa":"場所"},{"label":"B","text":"面积","meaningJa":"面積"},{"label":"C","text":"地区","meaningJa":"地域"},{"label":"D","text":"地面","meaningJa":"地面"}],"answer":"B","translationJa":"さらに占有面積が小さいため、所有者も駐車スペース探しで悩まなくて済む。","explanationJa":"「占地面积（占有面積・敷地面積）」は固定の複合名詞で、後ろの形容詞「小（小さい）」とも自然につながります。","tipJa":"「占地面积大／小（占有面積が大きい／小さい）」は不動産・都市交通・製品説明などで頻出する定型表現です。"},{"id":44,"section":"reading","partId":"R1","kind":"mcq","groupId":"hsk5-r1-42-45","promptZh":"其次是用途【44】。","options":[{"label":"A","text":"实用","meaningJa":"実用的である"},{"label":"B","text":"高档","meaningJa":"高級である"},{"label":"C","text":"有利","meaningJa":"有利である"},{"label":"D","text":"广泛","meaningJa":"幅広い"}],"answer":"D","translationJa":"第二に用途が幅広いことである。","explanationJa":"後ろに「适用于多种日常生活场景：上下班、接送孩子、外出买菜……（通勤・送迎・買い物など多様な生活シーンに適する）」と具体例が並んでいるため、「用途广泛（用途が広い）」の D が正解です。","tipJa":"「用途广泛（用途が広い）」は定番コロケーション！A「实用」は「电动自行车很实用」とは言いますが「用途实用」とは組み合わせません。"},{"id":45,"section":"reading","partId":"R1","kind":"mcq","groupId":"hsk5-r1-42-45","promptZh":"也不用考取驾照，上了年纪的人也可以驾驶，能【45】多方面需求。","options":[{"label":"A","text":"满足","meaningJa":"満たす"},{"label":"B","text":"实施","meaningJa":"実施する"},{"label":"C","text":"组合","meaningJa":"組み合わせる"},{"label":"D","text":"达成","meaningJa":"達成する"}],"answer":"A","translationJa":"運転免許を取る必要もなく高齢者も運転でき、多方面のニーズを満たすことができる。","explanationJa":"目的語が「需求（ニーズ・要求）」なので、「满足需求（ニーズを満たす）」の A が唯一の正しい組み合わせです。D「达成」は「达成协议／目标（合意・目標を達成する）」に使います。","tipJa":"「满足＋需求／要求／条件（ニーズ・要求・条件を満たす）」はHSK最重要コロケーションの一つです。動詞＋目的語のペアで暗記しましょう。"},{"id":46,"section":"reading","partId":"R2","kind":"match_bank","groupId":"hsk5-r2-46-50","promptZh":"第 1 段（1番目）","answer":"C","translationJa":"1番目（冒頭）：本学2024〜2025年度第2学期の第1次履修登録の日程と、事前の教学計画確認の案内（段落C）。","explanationJa":"通知文の冒頭には「いつ・何のお知らせか」を明確に示す段落が来ます。Cは「我校2024～2025学年第二学期第一轮选课……」と全体主題と第1次登録期間を提示しており、明確な導入段落です。","tipJa":"段落並べ替えでは、指示代名詞（「此计划」など）を含まず、話題全体を初出で提示する段落をまず1番目に特定しましょう。"},{"id":47,"section":"reading","partId":"R2","kind":"match_bank","groupId":"hsk5-r2-46-50","promptZh":"第 2 段（2番目）","answer":"B","translationJa":"2番目：教学計画に卒業必要単位が明記されていることの説明（段落B）。","explanationJa":"Cの末尾にある「本专业教学计划（専攻の教学計画）」を、Bの冒頭「此计划中……（この計画の中には……）」がそのまま指し示して受けているため、C→Bの連鎖が確定します。","tipJa":"「此＋名詞（この〜）」という書き言葉の指示語は、直前の文末の名詞を受ける最強の接着剤です！"},{"id":48,"section":"reading","partId":"R2","kind":"match_bank","groupId":"hsk5-r2-46-50","promptZh":"第 3 段（3番目）","answer":"E","translationJa":"3番目：教学計画の要件を把握したうえでプラットフォームから履修登録する手順（段落E）。","explanationJa":"Bで「教学計画の学分要求」を説明した後、Eが「在了解教学计划规定的要求后……（教学計画に定められた要件を理解した後に……）」と受けて具体的な登録手順へ進みます。","tipJa":"「在了解〜后（〜を理解した後で）」という時間・手順のつなぎ表現に注目すると、B→Eの流れが一目瞭然です。"},{"id":49,"section":"reading","partId":"R2","kind":"match_bank","groupId":"hsk5-r2-46-50","promptZh":"第 4 段（4番目）","answer":"D","translationJa":"4番目：1月8日の第1次登録終了後の閉講扱いと第2次履修登録（1月10日〜13日）の案内（段落D）。","explanationJa":"Eで第1次登録の手順を述べた後、時間軸に沿ってDが「1月8日选课结束后……参加第二轮选课（1月8日の登録終了後……第2次登録に参加できる）」と次のフェーズを説明します。","tipJa":"日程案内では日付の時系列（1月1日〜8日 → 1月8日終了後 → 1月10日〜13日）をたどれば迷いません。"},{"id":50,"section":"reading","partId":"R2","kind":"match_bank","groupId":"hsk5-r2-46-50","promptZh":"第 5 段（5番目）","answer":"A","translationJa":"5番目（結び）：2回の履修登録期間内の厳守と教務課への問い合わせ先（段落A）。","explanationJa":"Aには「在两轮选课期间（2回の履修登録期間内に）」とあり、第1次（C）と第2次（D）の両方が述べられた後でなければ置けません。また「请联系教务处（教務課へ連絡を）」は通知文の定番の結びです。","tipJa":"「两轮（2回とも）」という総括表現と「問い合わせ先案内」は、通知文の最終段落を示す決定的なサインです。"},{"id":51,"section":"reading","partId":"R2","kind":"match_bank","groupId":"hsk5-r2-51-55","promptZh":"第 1 段（1番目）","answer":"C","translationJa":"1番目（冒頭）：王勃の人物紹介と、長安で杜姓の友人と親交を結んだ背景（段落C）。","explanationJa":"Cは「王勃是中国古代的著名文学家。他在长安时，交到了一位姓杜的朋友」と登場人物と舞台を初めて紹介しており、物語の出発点として唯一適切です。","tipJa":"「一位姓杜的朋友（ある杜姓の友人）」という不定の初出表現に対し、Aは「这位朋友（この友人）」と既出扱いしているため、必ずCが先に来ます。"},{"id":52,"section":"reading","partId":"R2","kind":"match_bank","groupId":"hsk5-r2-51-55","promptZh":"第 2 段（2番目）","answer":"A","translationJa":"2番目：ある日友人を訪ねると、黙って悲しそうな様子をしていた場面（段落A）。","explanationJa":"Cで「一位姓杜的朋友」と親しい関係を紹介した後、Aが「一天，王勃像平常一样去找这位朋友（ある日いつものようにこの友人を訪ねると）」と具体的な出来事に入ります。","tipJa":"物語文では「背景紹介（C）→『一天（ある日）』（A）」で事件が始まるのが王道構成です。"},{"id":53,"section":"reading","partId":"R2","kind":"match_bank","groupId":"hsk5-r2-51-55","promptZh":"第 3 段（3番目）","answer":"E","translationJa":"3番目：理由を尋ねると、辺鄙な蜀州への赴任を命じられたと知らされた場面（段落E）。","explanationJa":"Aで「一副难过的样子（悲しそうな様子）」を見た直後に、Eで「王勃连忙询问朋友发生了什么事（慌てて何があったか尋ねた）」と行動がつながります。","tipJa":"「見た（见到难过的样子）」→「すぐ尋ねた（连忙询问）」という因果・動作の直接連鎖を見抜けばA→Eは確実です。"},{"id":54,"section":"reading","partId":"R2","kind":"match_bank","groupId":"hsk5-r2-51-55","promptZh":"第 4 段（4番目）","answer":"D","translationJa":"4番目：出発の日が迫り、別れ際に『送杜少府之任蜀州』を詠んだ場面（段落D）。","explanationJa":"Eの「再过几天就要出发了（あと数日で出発する）」を受けて、Dが「日子过得很快，转眼朋友就要离开长安了（あっという間に長安を離れる日になった）」と時間を進め、送別詩を執筆します。","tipJa":"Dの末尾で初めて詩の題名『送杜少府之任蜀州』が登場し、それをBの「这首诗（この詩）」が受けるため、D→Bの順番も100％確定します。"},{"id":55,"section":"reading","partId":"R2","kind":"match_bank","groupId":"hsk5-r2-51-55","promptZh":"第 5 段（5番目）","answer":"B","translationJa":"5番目（結び）：その詩の名句「海内存知己，天涯若比邻」の意味と今日までの評価（段落B）。","explanationJa":"Bは「这首诗的第三句非常经典……（この詩の第3句は非常に名高い……）」とDの詩を受け、「至今仍然被人们用来表达友情（今日でも友情の表現に使われている）」と現代まで広げて締めくくります。","tipJa":"「这首诗」という指示語と「流传千年，至今仍然〜」という歴史的意義のまとめは、伝記・文化エッセイの典型的な最終段落です。"},{"id":56,"section":"reading","partId":"R3","kind":"mcq","groupId":"hsk5-r3-56-58","promptZh":"孙凯为什么要在理发镜旁边安装音箱？","options":[{"label":"A","text":"给顾客提供乐趣","meaningJa":"利用客に楽しみを提供するため"},{"label":"B","text":"提醒等候的顾客","meaningJa":"待っている客に知らせるため"},{"label":"C","text":"吸引路过的行人","meaningJa":"通りすがりの歩行者を引きつけるため"},{"label":"D","text":"便于和老人沟通","meaningJa":"高齢者と意思疎通をしやすくするため"}],"answer":"A","translationJa":"孫凱さんはなぜ理髪鏡の横にスピーカーを取り付けたのですか？","explanationJa":"第2段落に「理发镜旁边还安装了音箱。孙凯希望音乐可以给顾客带来些许乐趣（音楽が利用客にささやかな楽しみをもたらしてほしい）」と明記されているため、Aが正解です。","tipJa":"「带来些许乐趣（少しの楽しみをもたらす）」→「提供乐趣（楽しみを提供する）」の言い換えです。「些许（少しの・わずかな）」はHSK5級の書き言葉重要語！"},{"id":57,"section":"reading","partId":"R3","kind":"mcq","groupId":"hsk5-r3-56-58","promptZh":"根据最后一段，孙凯口中的“有爱”是指：","options":[{"label":"A","text":"说话幽默","meaningJa":"話し方がユーモラスなこと"},{"label":"B","text":"做志愿服务","meaningJa":"ボランティア活動をすること"},{"label":"C","text":"充分尊重顾客","meaningJa":"顧客を十分に尊重すること"},{"label":"D","text":"视团队成员如同亲人","meaningJa":"チームメンバーを家族同然に思うこと"}],"answer":"B","translationJa":"最終段落によると、孫凱さんの言う「有爱（愛がある）」とは何を指しますか？","explanationJa":"最終段落に「‘爱’是指志愿服务，‘才’是指技能进步（『愛』はボランティア活動を、『才』は技術向上を指す）」と直接定義されているため、Bが正解です。","tipJa":"「A是指B（AとはBを指す）」という定義文はそのまま設問の根拠になります。設問が「根据最后一段」と段落指定しているときは真っ先にそこへ飛びましょう。"},{"id":58,"section":"reading","partId":"R3","kind":"mcq","groupId":"hsk5-r3-56-58","promptZh":"未来，孙凯将会怎么做？","options":[{"label":"A","text":"调低理发费用","meaningJa":"散髪料金を引き下げる"},{"label":"B","text":"提升理发技能","meaningJa":"理髪技術を高める"},{"label":"C","text":"开理发培训班","meaningJa":"理髪養成講座を開く"},{"label":"D","text":"增加服务项目","meaningJa":"サービス項目を増やす"}],"answer":"B","translationJa":"今後、孫凱さんはどのようにする予定ですか？","explanationJa":"最終文に「他打算平时再多下点儿功夫，提升技术水平，把志愿服务长久地做下去（普段からさらに努力して技術水準を高め、ボランティアを長く続けるつもりだ）」とあるため、B「提升理发技能」が正解です。","tipJa":"「下功夫（努力を注ぐ・精を出す）」と「打算（〜するつもりだ）」が未来の計画を表すキーワードです。"},{"id":59,"section":"reading","partId":"R3","kind":"mcq","groupId":"hsk5-r3-59-62","promptZh":"根据第一段，那幅教学挂图：","options":[{"label":"A","text":"画得准确形象","meaningJa":"正確かつ生き生きと描かれている"},{"label":"B","text":"在校图书馆展出","meaningJa":"大学図書館で展示されている"},{"label":"C","text":"由教授们集体创作","meaningJa":"教授たちの共同制作である"},{"label":"D","text":"采用了3D打印技术","meaningJa":"3Dプリント技術を採用している"}],"answer":"A","translationJa":"第1段落によると、その教育用掛図はどのようなものですか？","explanationJa":"第1段落に「画中发动机的内部结构、材料特征等，几乎和真的一样，甚至还带着几分‘动感’（本物そっくりで躍動感さえある）」と描写されているため、A「画得准确形象」が正解です。","tipJa":"Bは「院史馆（学院歴史館）」であって図書館ではないため×。Cは施岳定個人の創作、Dは手描きなので×です。"},{"id":60,"section":"reading","partId":"R3","kind":"mcq","groupId":"hsk5-r3-59-62","promptZh":"第三段主要讲的是：","options":[{"label":"A","text":"内燃机的内部结构","meaningJa":"内燃機関の内部構造"},{"label":"B","text":"制作手工挂图的原因","meaningJa":"手作り掛図を制作する一般的な理由"},{"label":"C","text":"工程专业学生的课程安排","meaningJa":"工学専攻学生のカリキュラム"},{"label":"D","text":"施岳定画教学挂图的原因","meaningJa":"施岳定が教育用掛図を描いた理由"}],"answer":"D","translationJa":"第3段落は主に何について述べていますか？","explanationJa":"第3段落では、学生が複雑な機械を理解しにくいこと、当時の教材掛図が不鮮明だったことから「于是施岳定产生了一个想法——把这些复杂机器结构用立体画的方式展示出来」と述べており、D「施岳定画教学挂图的原因」が最も的確です。","tipJa":"B「制作手工挂图的原因」は主語が曖昧かつ本文にない「手工挂图」という語を使った紛らわしい罠！本文の表現「施岳定」「教学挂图」に忠実な D を選びましょう。"},{"id":61,"section":"reading","partId":"R3","kind":"mcq","groupId":"hsk5-r3-59-62","promptZh":"上文主要体现出施岳定是一个怎样的人？","options":[{"label":"A","text":"热爱教育","meaningJa":"教育を深く愛する人"},{"label":"B","text":"热情活泼","meaningJa":"情熱的で活発な人"},{"label":"C","text":"善良勇敢","meaningJa":"親切で勇敢な人"},{"label":"D","text":"珍惜人才","meaningJa":"人材を大切にする人"}],"answer":"A","translationJa":"上の文章は、施岳定氏がどのような人物であることを主に表していますか？","explanationJa":"学生の理解を助けるため丸3か月かけて掛図を描き、第4段落でも「凭借对教育事业的热爱，他白天上课、搞科研，晚上集中精力画图（教育事業への愛を支えに昼は授業と研究、夜は作図に励んだ）」と明言されているため、A「热爱教育」が正解です。","tipJa":"人物評価問題では本文に直結するキーワード（「对教育事业的热爱」）を根拠にするのが安全です。一般的な美徳（B・C・D）に惑わされないようにしましょう。"},{"id":62,"section":"reading","partId":"R3","kind":"mcq","groupId":"hsk5-r3-59-62","promptZh":"根据上文，可以知道什么？","options":[{"label":"A","text":"学校奖励了施岳定","meaningJa":"学校は施岳定を表彰した"},{"label":"B","text":"工程画逐渐流行起来","meaningJa":"工程画が次第に流行した"},{"label":"C","text":"施岳定的画在教材中出现","meaningJa":"施岳定の絵が教科書に掲載された"},{"label":"D","text":"施岳定很在乎同事的评价","meaningJa":"施岳定は同僚の評価をとても気にしていた"}],"answer":"C","translationJa":"上の文章から何がわかりますか？","explanationJa":"最終段落に「其中许多图片成为了教材插图，帮助了许多学生（その多くが教科書の挿絵となり多くの学生を助けた）」とあるため、C「施岳定的画在教材中出现」が正解です。","tipJa":"「成为教材插图（教科書の挿絵になった）」→「在教材中出现（教科書に登場した）」の言い換え。A・B・Dはいずれも本文に記載のない内容です。"},{"id":63,"section":"reading","partId":"R3","kind":"mcq","groupId":"hsk5-r3-63-66","promptZh":"第一段中画线部分的意思最可能是：","promptSubZh":"※ 画线部分：「学而知不足」","options":[{"label":"A","text":"茶文化内容深厚","meaningJa":"茶文化の内容が奥深いこと"},{"label":"B","text":"茶文化有不足之处","meaningJa":"茶文化に不十分な点があること"},{"label":"C","text":"茶文化普及度不高","meaningJa":"茶文化の普及度が高くないこと"},{"label":"D","text":"很欣赏现在的茶文化","meaningJa":"現在の茶文化をとても高く評価していること"}],"answer":"A","translationJa":"第1段落の下線部（「学而知不足」）の意味として最も適切なのはどれですか？","explanationJa":"「学而知不足」は『礼記』由来の語で「学べば学ぶほど自分の知識の足りなさを知る」という意味です。直前に「興味がますます濃くなり、認識も深まった」とあることから、中国茶文化があまりに奥深く学び尽くせないこと（A「茶文化内容深厚」）を表しています。","tipJa":"「不足」の文字だけを見て B（茶文化に欠点がある）と誤読させる超定番の罠！主語は「自分の知識の不足」であり、対象（茶文化）の奥深さを讃える表現です。"},{"id":64,"section":"reading","partId":"R3","kind":"mcq","groupId":"hsk5-r3-63-66","promptZh":"桑国亚是如何学习茶艺的？","options":[{"label":"A","text":"向名师请教","meaningJa":"名師に教えを乞うた"},{"label":"B","text":"参观制茶工厂","meaningJa":"製茶工場を見学した"},{"label":"C","text":"浏览茶艺视频","meaningJa":"茶芸の動画を閲覧した"},{"label":"D","text":"接触各地茶园","meaningJa":"各地の茶園を巡り触れた"}],"answer":"D","translationJa":"桑国亜さんはどのようにして茶芸を学びましたか？","explanationJa":"第2段落に「桑国亚开始正式学习茶艺，他走遍了中国各地茶园（本格的に茶芸を学び始め、中国各地の茶園を巡り歩いた）」とあるため、D「接触各地茶园」が正解です。","tipJa":"「走遍各地茶园（各地の茶園をくまなく回る）」→「接触各地茶园」の言い換え。「遍（くまなく・一通り）」は結果補語としてよく出ます。"},{"id":65,"section":"reading","partId":"R3","kind":"mcq","groupId":"hsk5-r3-63-66","promptZh":"桑国亚为了分享中国茶文化做了什么？","options":[{"label":"A","text":"举办茶文化节","meaningJa":"茶文化祭を開催した"},{"label":"B","text":"组织茶艺表演","meaningJa":"茶芸ショーを企画した"},{"label":"C","text":"研制茶叶新品种","meaningJa":"茶葉の新種を開発した"},{"label":"D","text":"担任茶文化课程老师","meaningJa":"茶文化の授業の教師を務めた"}],"answer":"D","translationJa":"桑国亜さんは中国茶文化を分かち合うために何をしましたか？","explanationJa":"第3段落に「对茶的热爱让桑国亚开始向更多的人分享中国茶文化。他回国后在学校里教茶文化课（帰国後、学校で茶文化の授業を教えている）」とあるため、D「担任茶文化课程老师」が正解です。","tipJa":"「教茶文化课（茶文化の授業を教える）」→「担任茶文化课程老师（茶文化コースの教師を務める）」の書き換えです。"},{"id":66,"section":"reading","partId":"R3","kind":"mcq","groupId":"hsk5-r3-63-66","promptZh":"根据上文，下列哪项正确？","options":[{"label":"A","text":"福建人习惯饭前泡茶","meaningJa":"福建の人は食前にお茶を淹れる習慣がある"},{"label":"B","text":"适当喝红茶可以提神","meaningJa":"適度に紅茶を飲むと目が覚める"},{"label":"C","text":"喝茶让桑国亚忘记烦恼","meaningJa":"お茶を飲むと桑国亜は悩みを忘れられる"},{"label":"D","text":"竹叶青是广州特有茶叶","meaningJa":"竹葉青は広州特有の茶葉である"}],"answer":"C","translationJa":"上の文章によると、次のうち正しいのはどれですか？","explanationJa":"第4段落に「桑国亚发现，陷入烦恼时，泡一杯茶细细品味能让人忘记那些令人头疼的问题（悩みに陥ったとき一杯のお茶を味わえば頭を悩ませる問題を忘れられる）」とあるため、Cが正解です。","tipJa":"A・B・Dは見事な細部すり替えの罠！福建は「晚饭后（食後）」、提神は「绿茶（緑茶）」で紅茶は「暖胃」、竹叶青は「成都（四川）」です。正誤問題では名詞・時間・地名の組み合わせを必ず本文と突き合わせましょう。"},{"id":67,"section":"reading","partId":"R3","kind":"mcq","groupId":"hsk5-r3-67-70","promptZh":"线下认养人：","options":[{"label":"A","text":"每年都会捐钱","meaningJa":"毎年寄付をする"},{"label":"B","text":"要学会训练动物","meaningJa":"動物の訓練を学ぶ必要がある"},{"label":"C","text":"有进馆体验的机会","meaningJa":"獣舎に入って体験する機会がある"},{"label":"D","text":"可以自由出入动物园","meaningJa":"動物園に自由に出入りできる"}],"answer":"C","translationJa":"オフライン認養者（里親）について正しいのはどれですか？","explanationJa":"第2段落に「线下认养人每年可以进入场馆深度体验一次，可以帮忙打扫卫生，了解饲养员日常如何照顾动物（年1回獣舎に入ってディープな体験ができる）」とあるため、C「有进馆体验的机会」が正解です。","tipJa":"「每年可以进入场馆深度体验一次」なので、D「自由出入（自由に出入り）」は言い過ぎで×。頻度や制限条件（「一次」など）の読み落としに気をつけましょう。"},{"id":68,"section":"reading","partId":"R3","kind":"mcq","groupId":"hsk5-r3-67-70","promptZh":"关于“云认养”模式，可以知道：","options":[{"label":"A","text":"已在全国推广","meaningJa":"すでに全国で普及している"},{"label":"B","text":"限制认养数量","meaningJa":"認養数を制限している"},{"label":"C","text":"必须签订协议书","meaningJa":"契約書に署名しなければならない"},{"label":"D","text":"能通过直播观看动物","meaningJa":"ライブ配信を通じて動物を見られる"}],"answer":"D","translationJa":"「クラウド認養（云认养）」モデルについて何がわかりますか？","explanationJa":"第2段落に「线上认养人可以通过每月一次的点对点直播，观看到自己认养的小动物（月1回の個別ライブ配信を通じて自分の認養動物を見られる）」と明記されているため、Dが正解です。","tipJa":"「云〜（クラウド〜／オンライン〜）」は「云认养」「云旅游」「云办公」など現代中国語で頻出する接頭表現です。「点对点直播（1対1ライブ配信）」も合わせて押さえましょう。"},{"id":69,"section":"reading","partId":"R3","kind":"mcq","groupId":"hsk5-r3-67-70","promptZh":"动物认养有什么意义？","options":[{"label":"A","text":"增强青少年责任感","meaningJa":"青少年の責任感を高める"},{"label":"B","text":"防止动物受到伤害","meaningJa":"動物が傷つけられるのを防ぐ"},{"label":"C","text":"有效禁止违法动物买卖","meaningJa":"違法な動物売買を有効に禁止する"},{"label":"D","text":"让人们更加关注野生动物","meaningJa":"人々が野生動物により関心を向けるようにする"}],"answer":"D","translationJa":"動物認養（里親制度）にはどのような意義がありますか？","explanationJa":"最終段落に「更重要的是加强了动物园和公众之间的联结，通过这种深度的体验方式让更多人关注、支持野生动物保护（より多くの人が野生動物保護に関心を持ち支援するようにする）」とあるため、Dが正解です。","tipJa":"「不仅A，更重要的是B（Aだけでなく、さらに重要なのはBだ）」の後ろに筆者が最も伝えたい意義が書かれます！"},{"id":70,"section":"reading","partId":"R3","kind":"mcq","groupId":"hsk5-r3-67-70","promptZh":"下列哪项最适合做上文题目？","options":[{"label":"A","text":"认养动物需谨慎","meaningJa":"動物の里親になる際は慎重に"},{"label":"B","text":"动物认养实现共赢","meaningJa":"動物認養がウィンウィンを実現"},{"label":"C","text":"野生动物园的魅力","meaningJa":"サファリパークの魅力"},{"label":"D","text":"动物直播成新趋势","meaningJa":"動物ライブ配信が新トレンドに"}],"answer":"B","translationJa":"上の文章のタイトルとして最も適切なのはどれですか？","explanationJa":"文章全体が紅山森林動物園の「动物认养（動物認養）」制度を主題としており、人々に精神的な癒しや動物保護への関心を促しつつ動物園の収益も改善するという「双赢（ウィンウィン）」を軸にまとめているため、B「动物认养实现共赢」が最適です。","tipJa":"タイトル問題では、本文中のまとめ語「可以说是双赢（まさにウィンウィンと言える）」の言い換え「实现共赢」と中心テーマ「动物认养」の両方を含む B が決定打になります。Dは一部の話題（云认养）に偏りすぎているため×です。"},{"id":71,"section":"writing","partId":"W1","kind":"writing_task","isSubjective":true,"minChars":100,"image":"./images/hsk5/W1_q71.jpg","imageAltJa":"4コマ漫画：1コマ目＝李明と2人の仲間がスコップ・じょうろ・苗木を持って湖畔を歩く、2コマ目＝3人で協力して苗木を植え水をやる、3コマ目＝植樹後にスマホで自撮りし大きく育つ姿を想像する、4コマ目＝「三年后」に大きく育った木の下で再会し写真を撮ったり幹に触れたりして喜ぶ","promptZh":"请根据下面四张图，写一篇不少于100字的作文，写出发生在李明和伙伴们身上的故事。","translationJa":"下の4枚のイラストを見て、李明と仲間たちに起きた出来事を100字以上の中国語で書いてください。","explanationJa":"4コマ漫画作文は「起（状況と出発）→承（協力して植樹）→転（記念撮影と期待）→結（3年後の成長と感動）」の流れで各コマの要素を漏れなくつなぐことが高得点のコツです。①道具（铁锹・水壶・树苗）を持って出発、②分工合作（扶正・培土・浇水）、③合影留念と成長への期待（吹き出し）、④「三年后」の文字を踏まえて大木に育った喜びと環境保護の意義で締めくくりましょう。","tipJa":"100字以上が条件ですが、140〜180字程度で書くと描写が豊かになり高評価を狙えます。3コマ目と4コマ目の吹き出し（小樹→大木への成長イメージ）と「三年后」の時間経過を必ず文章に織り込みましょう。","modelAnswerZh":"一个阳光明媚的周末，李明和两位小伙伴相约去湖边植树。李明扛着铁锹，伙伴们拎着水壶、抱着树苗，一路欢声笑语。来到草地后，大家默契配合：一人扶正树苗，李明挥锹培土，另一人细心浇水。种完后，三人拍下合影，满怀期待地盼着小树早日成材。转眼三年过去，他们重返旧地，惊喜地看到小树苗已长成枝繁叶茂的大树，小鸟在枝头欢唱。望着亲手种下的大树，大家纷纷拍照留念，心中满是喜悦与自豪。","modelAnswerJa":"太陽が明るく照るある週末、李明と2人の仲間は約束して湖畔へ植樹に出かけた。李明はスコップを肩に担ぎ、仲間たちはじょうろを提げたり苗木を抱えたりして、道中ずっと笑い声が絶えなかった。草地に着くと皆で息を合わせて作業した。1人が苗木を真っ直ぐ支え、李明がスコップで土を盛り、もう1人が丁寧に水をやった。植え終えると3人で記念写真を撮り、苗木が一日も早く大きく育つよう胸を膨らませた。あっという間に3年が過ぎ、再びこの場所を訪れると、あの小さな苗木が枝葉を茂らせた大木に育ち、枝の上で小鳥が楽しそうにさえずっているのを見て大喜びした。自分たちの手で植えた大木を見上げながら、皆は次々と記念撮影をし、心は喜びと誇りでいっぱいになった。","rubricJa":["字数が100字以上（目安140〜180字）に達し、物語として完結しているか","主人公「李明」と仲間たちの名前・関係が自然に導入されているか","4コマすべての要素（道具を持って出発 → 協力して植樹・水やり → 記念撮影と期待 → 3年後の成長と再会）が時系列でつながっているか","「扛着铁锹」「分工合作／默契配合」「浇水」「合影留念」「枝繁叶茂」などHSK5級らしい動詞・成語を使えているか","最後に喜び・達成感・環境保護への思いなど前向きな結びが入っているか"]},{"id":72,"section":"writing","partId":"W2","kind":"writing_task","isSubjective":true,"minChars":200,"promptZh":"尝试可能会成功，也可能会失败，但不去试一试就永远不会成功。请写一篇不少于200字的作文，分享你曾经做过的一次尝试，以及你尝试后的感受。","translationJa":"試みは成功することもあれば失敗することもありますが、試してみなければ永遠に成功しません。あなたがかつて行ったある「試み（挑戦）」と、試みた後の感想について200字以上の作文で分かち合ってください。","explanationJa":"設問の2つの必須要素――①「曾经做过的一次尝试（かつて行った1回の試みの具体エピソード）」と②「尝试后的感受（試みた後の感想・学び）」――をバランスよく3段落構成（導入・葛藤 → 挑戦の過程と結果 → 感想と今後への展望）で書くのが王道です。成功談でも失敗談でも構いませんが、冒頭で「不安や迷い」を描いておくと、後半の成長や気づきに説得力が生まれます。","tipJa":"200字以上の課題では240〜300字程度が最も読みやすく高得点を狙えます。接続詞（因此・但・于是・虽然……但……・不仅……也……）を意識的に織り交ぜ、話し言葉に偏りすぎない自然な書き言葉でまとめましょう。","modelAnswerZh":"去年秋天，我做了一次令自己难忘的尝试——报名参加学校的中文演讲比赛。从小我就比较内向，一站在众人面前发言就会紧张得忘词，因此一开始我非常犹豫，担心在台上出丑。但转念一想，如果不迈出第一步，就永远无法克服胆怯，于是我鼓起勇气报了名。\\n\\n接下来的两周里，我每天坚持修改讲稿、对着镜子反复练习发音和手势，还请老师和朋友帮我提建议。比赛那天，虽然上台前心跳加速，但当我开口说出第一句话后，反而慢慢平静了下来，最终顺利完成了演讲，并获得了三等奖。\\n\\n这次尝试让我深刻体会到，害怕失败往往比失败本身更可怕。勇敢迈出第一步，不仅让我收获了自信，也让我看到了自己的无限可能。今后面对未知的挑战，我也会毫不犹豫地去试一试。","modelAnswerJa":"昨年の秋、私は自分にとって忘れられない挑戦をした。学校の中国語スピーチコンテストに応募したことだ。私は子どものころから比較的引っ込み思案で、人前に立って話すといつも緊張して言葉を忘れてしまうため、最初は壇上で恥をかくのではないかととても迷った。しかし考え直してみると、最初の一歩を踏み出さなければいつまでも臆病さを克服できないと思い、勇気を振り絞って申し込んだ。\\n\\nその後の2週間、私は毎日欠かさず原稿を推敲し、鏡に向かって発音やジェスチャーを繰り返し練習し、さらに先生や友人にもアドバイスを求めた。大会当日、登壇前は心臓が激しく鳴っていたが、最初の一言を口にするとかえって次第に落ち着きを取り戻し、無事にスピーチをやり遂げて3等賞を獲得することができた。\\n\\nこの挑戦を通じて、失敗を恐れる気持ちは往々にして失敗そのものより恐ろしいのだと深く実感した。勇敢に一歩を踏み出したことで自信を得ただけでなく、自分の無限の可能性にも気づくことができた。今後も未知の挑戦に直面したときは、迷わず一歩試してみようと思う。","rubricJa":["字数が200字以上（目安240〜300字）に達し、段落構成（背景→過程・結果→感想）が明確か","「かつて行った1回の試み」が具体的なエピソードとして描かれているか","「試みた後の感想・学び」が設問の趣旨（試みなければ成功しない）としっかり呼応しているか","「鼓起勇气」「反复练习」「反而」「不仅……也……」「深刻体会到」など中上級らしい表現・複文が使えているか","誤字脱字や日本語直訳の不自然な表現（「〜的尝试做了」などの語順ミス）がないか"]}]'),i=[{start:0,end:68.55,partId:"L1",labelJa:"試験開始案内・聴力第1部 説明"},{start:71.55,end:94.8,partId:"L1",questionIds:[1],labelJa:"第1問（商業保険の相談）"},{start:109.65,end:133.85,partId:"L1",questionIds:[2],labelJa:"第2問（国家博物館の予約）"},{start:148.9,end:173.5,partId:"L1",questionIds:[3],labelJa:"第3問（内装リフォームプラン）"},{start:188.65,end:211.7,partId:"L1",questionIds:[4],labelJa:"第4問（留学生の帰国就職）"},{start:226.55,end:253.05,partId:"L1",questionIds:[5],labelJa:"第5問（胡同の変化）"},{start:267.85,end:289.1,partId:"L1",questionIds:[6],labelJa:"第6問（天井の水漏れ）"},{start:304.05,end:327.1,partId:"L1",questionIds:[7],labelJa:"第7問（漢方パン）"},{start:342,end:366.4,partId:"L1",questionIds:[8],labelJa:"第8問（後払い機能）"},{start:381.35,end:403.45,partId:"L1",questionIds:[9],labelJa:"第9問（民族衣装の講座）"},{start:418.35,end:444.95,partId:"L1",questionIds:[10],labelJa:"第10問（結婚式のリングドッグ）"},{start:460.15,end:509.55,partId:"L1",questionIds:[11,12],labelJa:"第11〜12問 対話・第11問（写真と余白）"},{start:524.5,end:529.35,partId:"L1",questionIds:[12],labelJa:"第12問 設問"},{start:544.4,end:596.3,partId:"L1",questionIds:[13,14],labelJa:"第13〜14問 対話・第13問（テニス選手とコーチ）"},{start:611.3,end:615.15,partId:"L1",questionIds:[14],labelJa:"第14問 設問"},{start:629.9,end:675,partId:"L1",questionIds:[15,16],labelJa:"第15〜16問 対話・第15問（お掃除ロボット）"},{start:690.05,end:695.05,partId:"L1",questionIds:[16],labelJa:"第16問 設問"},{start:709.95,end:783.6,partId:"L1",questionIds:[17,18,19],labelJa:"第17〜19問 対話・第17問（青少年の心のケア）"},{start:798.5,end:804.25,partId:"L1",questionIds:[18],labelJa:"第18問 設問"},{start:819.15,end:825.6,partId:"L1",questionIds:[19],labelJa:"第19問 設問"},{start:840.4,end:853.45,partId:"L2",labelJa:"聴力第2部 説明"},{start:856.8,end:904.85,partId:"L2",questionIds:[20,21],labelJa:"第20〜21問 短文・第20問（高速鉄道アナウンス）"},{start:920.65,end:924.4,partId:"L2",questionIds:[21],labelJa:"第21問 設問"},{start:940.15,end:1005.65,partId:"L2",questionIds:[22,23],labelJa:"第22〜23問 短文・第22問（秋拾い「捡秋」）"},{start:1021.75,end:1025.55,partId:"L2",questionIds:[23],labelJa:"第23問 設問"},{start:1041.3,end:1115.25,partId:"L2",questionIds:[24,25,26],labelJa:"第24〜26問 短文・第24問（蘇洵の教育法）"},{start:1130.95,end:1135.25,partId:"L2",questionIds:[25],labelJa:"第25問 設問"},{start:1151.2,end:1155.4,partId:"L2",questionIds:[26],labelJa:"第26問 設問"},{start:1171.15,end:1253.25,partId:"L2",questionIds:[27,28,29],labelJa:"第27〜29問 短文・第27問（交通警察の温かい支援）"},{start:1269.1,end:1274.1,partId:"L2",questionIds:[28],labelJa:"第28問 設問"},{start:1290.05,end:1295.25,partId:"L2",questionIds:[29],labelJa:"第29問 設問"},{start:1311.15,end:1378.6,partId:"L2",questionIds:[30,31,32],labelJa:"第30〜32問 短文・第30問（習慣の置換理論）"},{start:1394.5,end:1401.1,partId:"L2",questionIds:[31],labelJa:"第31問 設問"},{start:1417.1,end:1422.85,partId:"L2",questionIds:[32],labelJa:"第32問 設問"},{start:1438.8,end:1509.95,partId:"L2",questionIds:[33,34,35],labelJa:"第33〜35問 短文・第33問（ダイエット論文）"},{start:1525.9,end:1532.3,partId:"L2",questionIds:[34],labelJa:"第34問 設問"},{start:1548.35,end:1553.85,partId:"L2",questionIds:[35],labelJa:"第35問 設問"},{start:1569.7,end:1571.75,partId:"L2",labelJa:"聴力試験終了"}],s={meta:a,parts:t,groups:e,questions:n,timeline:i};export{s as default,e as groups,a as meta,t as parts,n as questions,i as timeline};
